import type { CSSProperties } from 'react';

interface ImagePlaceholderProps {
  /** Shown under the icon in the editor, e.g. "Cover photo". Omit for the icon alone. */
  label?: string;
  className?: string;
  style?: CSSProperties;
}

/**
 * A neutral, brand-free empty image: a thin outline and an image icon in Text mixed into Paper,
 * so it reads on any brand and any ground without looking like content. Templates pass it as
 * `ImageBlock`'s `placeholder` instead of placeholder photos from a client folder (which leak one
 * client's imagery into another's documents). Inside `BrandKitProvider` it follows the brand's
 * `--foreground` / `--background`; outside it falls back to grey.
 */
export function ImagePlaceholder({ label, className, style }: ImagePlaceholderProps) {
  const ink = 'color-mix(in oklab, var(--foreground, #18181b) 38%, var(--background, #ffffff))';
  return (
    <div
      data-uhuu-image-placeholder=""
      className={className}
      style={{
        boxSizing: 'border-box',
        width: '100%',
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: '2mm',
        border: `0.25mm solid ${ink}`,
        color: ink,
        background: 'transparent',
        ...style,
      }}
    >
      <svg aria-hidden="true" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <rect x="3" y="3" width="18" height="18" rx="2" />
        <circle cx="9" cy="9" r="2" />
        <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21" />
      </svg>
      {label ? <span style={{ font: '500 2.6mm/1.2 var(--font-sans, sans-serif)' }}>{label}</span> : null}
    </div>
  );
}
