// Predicates for JSON-shaped values (payloads, brand kits). Internal.

export const isPlainObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);

export const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

/** A non-blank string, trimmed; `undefined` for anything else. */
export const textOf = (value) => (typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined);
