function finitePositive(value) {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0;
}

function normalizeGroupKey(value) {
  return typeof value === 'string' && value ? value : null;
}

function getKeepWithNextCount(value) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value));
  }

  return value ? 1 : 0;
}

/** `orphans` / `widows`: a positive line count, 2 when unset (CSS's default). */
const DEFAULT_FLOW_TEXT_LINES = 2;

function getLineCount(value) {
  return typeof value === 'number' && Number.isFinite(value) && value >= 1
    ? Math.floor(value)
    : DEFAULT_FLOW_TEXT_LINES;
}

const LINE_EPSILON = 0.01;
// Line boxes are differences of rects divided by an estimated transform scale: a page that holds
// exactly n lines must not lose one to a rounding error in the editor's zoomed preview.
const FIT_EPSILON = 0.01;

/**
 * The line metrics of a splittable item (`Static.FlowText`), validated: at least two lines, each
 * box below the one before it, start offsets increasing, the lines no taller than the item. The
 * origin they are measured from does not matter to a plan (every piece height is a difference).
 * Anything else cannot be split safely, so the item is planned whole, exactly as without metrics.
 */
function validFlowTextLines(entry, height) {
  const lines = entry?.lines;
  if (!Array.isArray(lines) || lines.length < 2) return null;
  const end = entry.end;
  if (typeof end !== 'number' || !Number.isFinite(end)) return null;
  let previousBottom = Number.NEGATIVE_INFINITY;
  let previousStart = -1;
  for (const line of lines) {
    const { top, bottom, start } = line ?? {};
    if (![top, bottom, start].every((value) => typeof value === 'number' && Number.isFinite(value))) return null;
    if (bottom < top - LINE_EPSILON || top < previousBottom - LINE_EPSILON) return null;
    if (start <= previousStart || start > end) return null;
    previousBottom = bottom;
    previousStart = start;
  }
  if (lines[lines.length - 1].bottom - lines[0].top > height + 1) return null;
  return entry;
}

/**
 * The height of the piece of a split item holding lines `first`..`last`: the item's own room above
 * its first line and below its last (padding, a label cell's border) on every piece, plus the
 * line boxes in between.
 */
function flowTextPieceHeight(entry, height, first, last) {
  const { lines } = entry;
  return Math.max(0, lines[0].top + (lines[last].bottom - lines[first].top) + (height - lines[lines.length - 1].bottom));
}

/**
 * Return the visible-fragment state for one flow item. It stays in the small
 * dependency-free core so the measurement algorithm and React renderer use
 * exactly the same continuation rules.
 */
export function getFlowFragmentState({
  itemIndex = -1,
  fragmentIndexes = [],
  groupKeys = [],
  pageIndex = 0,
  pageCount = 1,
  itemCount = 0,
  previousSourceIndex,
  // Internal render fast path: the React renderer already knows this while
  // walking a fragment, so avoid re-running `indexOf` for every visible item.
  fragmentIndex: knownFragmentIndex,
} = {}) {
  const fragmentIndex = Number.isInteger(knownFragmentIndex)
    ? knownFragmentIndex
    : fragmentIndexes.indexOf(itemIndex);
  const groupKey = normalizeGroupKey(groupKeys[itemIndex]);
  const previousFragmentItemIndex = fragmentIndex > 0
    ? fragmentIndexes[fragmentIndex - 1]
    : null;
  const previousFragmentGroupKey = previousFragmentItemIndex === null
    ? null
    : normalizeGroupKey(groupKeys[previousFragmentItemIndex]);
  const sourcePredecessorIndex = fragmentIndex > 0
    ? fragmentIndexes[fragmentIndex - 1]
    : previousSourceIndex ?? (itemIndex > 0 ? itemIndex - 1 : null);
  const previousSourceGroupKey = sourcePredecessorIndex !== null
    ? normalizeGroupKey(groupKeys[sourcePredecessorIndex])
    : null;
  const isFirstInGroup = Boolean(groupKey && previousSourceGroupKey !== groupKey);
  const isFirstInGroupOnPage = Boolean(groupKey && previousFragmentGroupKey !== groupKey);

  return {
    pageIndex,
    pageCount,
    itemIndex,
    fragmentIndex,
    groupKey: groupKey ?? undefined,
    isFirst: itemIndex === 0,
    isLast: itemCount > 0 && itemIndex === itemCount - 1,
    isFirstInFragment: fragmentIndex === 0,
    isLastInFragment: fragmentIndex >= 0 && fragmentIndex === fragmentIndexes.length - 1,
    isFirstInGroup,
    isFirstInGroupOnPage,
    // `isContinuation` refers to the virtual Flow page. `isGroupContinuation`
    // is the narrower signal for a repeated group header.
    isContinuation: pageIndex > 0,
    isGroupContinuation: Boolean(
      isFirstInGroupOnPage && !isFirstInGroup && previousSourceGroupKey === groupKey
    ),
  };
}

/**
 * Counters describing how much work one pagination pass cost. Purely
 * diagnostic — they never influence a pagination decision — but they make an
 * accidental quadratic regression fail a budget assertion instead of quietly
 * slowing every keystroke in the editor.
 */
export function createFlowPlanMetrics() {
  return {
    /** Leaf-item reads during chunking, keep lookahead, and avoid-break scans. */
    scannedItems: 0,
    /** Calls into the leaf chunker: one per page per track, plus retries. */
    chunkerCalls: 0,
    /**
     * Fresh-page retries computed, whether or not the retry was taken.
     * Unconstrained sequential content computes none: a retry is only reached
     * when a page already holds content and the next run either declares a
     * keep/avoid-break constraint or does not fit the remaining space.
     */
    freshPageAttempts: 0,
    /** Output pages produced. */
    pages: 0,
  };
}

/**
 * Split measured Flow items into virtual-page chunks. `headerGroupKeys` is
 * intentionally separate from item metadata's `groupKey`: existing callers
 * can keep using `groupKey` for avoid-break groups without opting into a
 * repeated measured header.
 *
 * `availableHeight` is the first page's region. `continuationHeight`, when
 * given, is the region of every later page (a page whose title is on its first
 * sheet only); without it every page has `availableHeight`.
 *
 * `lines`, when given, holds the line metrics of items that may split between
 * lines (`Static.FlowText`): `{ lines: [{ top, bottom, start }], end, justify }`
 * per item, `undefined` for the others. An item that does not fit the room left
 * is then split at a line, honoring `meta.orphans`/`meta.widows`, and the chunks
 * that hold its pieces say so in `splits`. Without `lines` the plan is exactly
 * the item-level plan.
 *
 * `breakReserve` (px), when given, is room kept free at the bottom of every
 * page the flow breaks from; the page it ends on keeps its full region, so a
 * flow that fits one page plans exactly as without it. 0 by default.
 *
 * `meta.growSheet` (set in the screen view only) places whole
 * an item that would otherwise be scaled onto a page of its own, and its sheet
 * grows by what the item needs beyond the page (`chunk.growth`, px). An item
 * taller than any page it could move to starts right under what precedes it;
 * one that fits a later page moves there whole, as without it. What follows
 * starts the next page.
 *
 * `headerGroupGrows[groupKey]` (the screen view only) makes a header group one
 * unit: its header once and every item of a contiguous run on one page. The
 * run fits the room left, or moves whole to a page that holds it, or, taller
 * than any page, starts right under what precedes it and grows the sheet as an
 * item with `meta.growSheet` does. Nothing in the run splits.
 */
export function distributeFlowItems({
  heights = [],
  keys = [],
  metas = [],
  availableHeight = 0,
  continuationHeight,
  headerGroupKeys = [],
  headerGroupHeights = {},
  headerGroupRepeats = {},
  headerGroupGrows = {},
  previousHeaderGroupKey,
  onUnplaceableItem,
  lines: itemLines,
  breakReserve,
  // Internal, used by distributeFlowColumns. `window` paginates a slice of the
  // caller's arrays without copying them, and `maxChunks` stops once that many
  // chunks are closed. Chunks are built strictly left to right and the group
  // header pass below only looks backwards, so a bounded run returns exactly
  // the chunks an unbounded run would have produced first. `fixedSheets`: the
  // pages never grow (`meta.growSheet` is ignored).
  window: itemWindow,
  maxChunks = 0,
  fixedSheets = false,
  metrics,
} = {}) {
  const windowIndexes = itemWindow?.indexes;
  const windowOffset = itemWindow?.offset ?? 0;
  const itemCount = windowIndexes
    ? Math.max(0, windowIndexes.length - windowOffset)
    : heights.length;
  // Chunk indexes stay window-local; `at` resolves them onto the caller's arrays.
  const at = windowIndexes ? (index) => windowIndexes[windowOffset + index] : (index) => index;
  const normalizedAvailableHeight = finitePositive(availableHeight) || Number.POSITIVE_INFINITY;
  const normalizedContinuationHeight = finitePositive(continuationHeight) || normalizedAvailableHeight;
  const chunks = [{ indexes: [], keys: [] }];
  let currentHeight = 0;

  // The region of the chunk being filled. Chunks are never left empty before the last one, so a
  // chunk's position is its page: the first page, then continuation pages.
  const pageCapacity = () => (chunks.length > 1 ? normalizedContinuationHeight : normalizedAvailableHeight);
  // `breakReserve`: a page the flow breaks from keeps `reserve` free at its bottom; the page it
  // ends on uses its full region (decideReserve, below). A reserve of a page or more is ignored.
  const reserve = finitePositive(breakReserve);
  const chunkReserved = new Map();
  const capacity = () => {
    const base = pageCapacity();
    return reserve && reserve < base && chunkReserved.get(currentChunk()) ? base - reserve : base;
  };
  const currentChunk = () => chunks[chunks.length - 1];
  const currentLastIndex = () => {
    const indexes = currentChunk().indexes;
    return indexes.length ? indexes[indexes.length - 1] : null;
  };
  const currentHasContent = () => (
    currentChunk().indexes.length > 0 || Boolean(currentChunk().unplaceable)
  );

  const getHeaderGroupKey = (index) => normalizeGroupKey(headerGroupKeys[at(index)]);
  const getHeaderHeight = (groupKey) => finitePositive(headerGroupHeights[groupKey] ?? 0);
  const shouldRepeatHeader = (groupKey) => headerGroupRepeats[groupKey] !== false;
  const needsGroupHeader = (index, previousIndex) => {
    const groupKey = getHeaderGroupKey(index);
    if (!groupKey) return false;

    if (previousIndex === null || previousIndex === undefined) {
      const previousSourceGroupKey = index > 0
        ? getHeaderGroupKey(index - 1)
        : normalizeGroupKey(previousHeaderGroupKey);
      return previousSourceGroupKey !== groupKey || shouldRepeatHeader(groupKey);
    }

    return getHeaderGroupKey(previousIndex) !== groupKey;
  };
  const getItemHeightWithHeader = (index, previousIndex) => {
    const groupKey = getHeaderGroupKey(index);
    return finitePositive(heights[at(index)]) + (
      groupKey && needsGroupHeader(index, previousIndex) ? getHeaderHeight(groupKey) : 0
    );
  };
  // `meta.growSheet`: whether the item grows its sheet where it would otherwise be scaled, and
  // whether it is taller than every page it could still move to (from the first page, a
  // continuation page too), so it starts right under what precedes it.
  const growsSheet = (index) => !fixedSheets && Boolean((metas[at(index)] ?? {}).growSheet);
  const tallerThanAnyPage = (height) => (
    height > Math.max(pageCapacity(), normalizedContinuationHeight) + FIT_EPSILON
  );
  // `headerGroupGrows`: a header group that is one unit on one page. `growingRunEnd` is the last
  // index of the contiguous run starting at `index`, or -1 when the group does not grow or `index`
  // is not the run's first item (a run is placed at once, from its first item).
  const groupGrows = (groupKey) => !fixedSheets && Boolean(groupKey && headerGroupGrows[groupKey]);
  const growingRunEnd = (index) => {
    const groupKey = getHeaderGroupKey(index);
    if (!groupGrows(groupKey)) return -1;
    const previousKey = index > 0 ? getHeaderGroupKey(index - 1) : normalizeGroupKey(previousHeaderGroupKey);
    if (previousKey === groupKey) return -1;
    let end = index;
    while (end + 1 < itemCount && getHeaderGroupKey(end + 1) === groupKey) end += 1;
    return end;
  };
  // The run's height: its header once, then every item.
  const growingRunHeight = (start, end, previousIndex) => {
    let height = getItemHeightWithHeader(start, previousIndex);
    for (let index = start + 1; index <= end; index += 1) {
      if (metrics) metrics.scannedItems += 1;
      height += finitePositive(heights[at(index)]);
    }
    return height;
  };
  const getAvoidBreakGroupKey = (index) => {
    const meta = metas[at(index)] ?? {};
    return meta.avoidBreakInside && meta.groupKey ? meta.groupKey : null;
  };

  // --- line splitting (`lines`): inert without line metrics --------------------------------
  // The header a piece is planned with: the first piece follows the item's normal header rule; a
  // continuation piece always starts a page, where a repeatable header repeats.
  const getHeaderHeightFor = (index, previousIndex) => {
    const groupKey = getHeaderGroupKey(index);
    return groupKey && needsGroupHeader(index, previousIndex) ? getHeaderHeight(groupKey) : 0;
  };
  const getContinuationHeaderHeight = (index) => {
    const groupKey = getHeaderGroupKey(index);
    return groupKey && shouldRepeatHeader(groupKey) ? getHeaderHeight(groupKey) : 0;
  };
  const splittableCache = new Map();
  // Whether the caller has line metrics for the item, without reading them: an item's lines are
  // only read when it does not fit whole (FlowArea reads them from the DOM on demand).
  const hasLines = (index) => Boolean(itemLines) && at(index) in itemLines;
  /**
   * The line metrics an item splits with, or null: no metrics, `avoidBreakInside`, or a line
   * (with its header) taller than a page, which no split can place.
   */
  const getSplittable = (index) => {
    if (!hasLines(index)) return null;
    if (splittableCache.has(index)) return splittableCache.get(index);
    const meta = metas[at(index)] ?? {};
    const height = finitePositive(heights[at(index)]);
    let entry = meta.avoidBreakInside ? null : validFlowTextLines(itemLines[at(index)], height);
    if (entry) {
      const groupKey = getHeaderGroupKey(index);
      const header = groupKey ? getHeaderHeight(groupKey) : 0;
      const page = Math.min(normalizedAvailableHeight, normalizedContinuationHeight);
      for (let line = 0; line < entry.lines.length; line += 1) {
        if (flowTextPieceHeight(entry, height, line, line) + header > page + FIT_EPSILON) {
          entry = null;
          break;
        }
      }
    }
    const result = entry
      ? {
        entry,
        height,
        count: entry.lines.length,
        orphans: getLineCount(meta.orphans ?? entry.orphans),
        widows: getLineCount(meta.widows ?? entry.widows),
      }
      : null;
    splittableCache.set(index, result);
    return result;
  };
  // The pieces placed in each chunk: chunk -> Map(item index -> [first line, last line]).
  const chunkPieces = new Map();

  // --- room at a page break (`breakReserve`): inert at 0 ----------------------------------------
  // Decided when an empty page takes its first content, from what is left of the flow laid out in
  // sequence from there: it either fits this page, which the flow then ends on (full region), or
  // it does not, and the flow breaks from this page (`reserve` is kept free). A forced break
  // further on is a break too. A last item that cannot split ends the flow on its own page.
  let sequentialRest = null; // sequentialRest[i]: items i.. laid out in sequence after item i - 1
  let forcedBreakAhead = null; // forcedBreakAhead[i]: a break is forced somewhere after item i starts
  const prepareReserve = () => {
    sequentialRest = new Array(itemCount + 1).fill(0);
    forcedBreakAhead = new Array(itemCount + 1).fill(false);
    for (let index = itemCount - 1; index >= 0; index -= 1) {
      sequentialRest[index] = sequentialRest[index + 1] + getItemHeightWithHeader(index, index > 0 ? index - 1 : null);
      const meta = metas[at(index)] ?? {};
      const next = index + 1 < itemCount ? metas[at(index + 1)] ?? {} : {};
      forcedBreakAhead[index] = forcedBreakAhead[index + 1] ||
        Boolean(next.breakBefore) ||
        Boolean(meta.breakAfter && index < itemCount - 1);
    }
  };
  const restFits = (index, firstLine, splittable) => {
    if (forcedBreakAhead[index]) return false;
    const own = firstLine > 0
      ? flowTextPieceHeight(splittable.entry, splittable.height, firstLine, splittable.count - 1) +
        getContinuationHeaderHeight(index)
      : getItemHeightWithHeader(index, null);
    if (own + sequentialRest[index + 1] <= pageCapacity() + FIT_EPSILON) return true;
    return index === itemCount - 1 && firstLine === 0 && !(hasLines(index) && getSplittable(index));
  };
  // Called with the item (or the piece of a split item) about to take an empty page.
  const decideReserve = (index, firstLine = 0, splittable = null) => {
    if (!reserve || currentHasContent()) return;
    const chunk = currentChunk();
    if (chunkReserved.has(chunk)) return;
    if (!sequentialRest) prepareReserve();
    chunkReserved.set(chunk, !restFits(index, firstLine, splittable));
  };

  const getAvoidBreakGroupHeight = (startIndex, groupKey, previousIndex) => {
    let height = 0;
    let priorIndex = previousIndex;

    for (let index = startIndex; index < itemCount; index += 1) {
      if (getAvoidBreakGroupKey(index) !== groupKey) break;
      if (metrics) metrics.scannedItems += 1;
      height += getItemHeightWithHeader(index, priorIndex);
      priorIndex = index;
    }

    return height;
  };

  const getKeepWithNextHeight = (index, count, { currentHeight, ownHeight, stopEarly } = {}) => {
    let height = 0;
    let priorIndex = index;

    for (let offset = 1; offset <= count; offset += 1) {
      const nextIndex = index + offset;
      if (nextIndex >= itemCount) break;
      if (metrics) metrics.scannedItems += 1;
      // A growing group counts whole, so a heading kept with a table stays with the whole table.
      const runEnd = growingRunEnd(nextIndex);
      const nextHeight = runEnd >= 0
        ? growingRunHeight(nextIndex, runEnd, priorIndex)
        : getItemHeightWithHeader(nextIndex, priorIndex);
      // An item or group that grows its sheet starts right under its predecessor, whatever room is left.
      if ((runEnd >= 0 || growsSheet(nextIndex)) && tallerThanAnyPage(nextHeight)) break;
      // An item that splits keeps its predecessor with its first piece: when it does not fit
      // whole, only its first `orphans` lines have to follow (a heading over a long paragraph).
      const splittable = hasLines(nextIndex) &&
        currentHeight + (ownHeight + height + nextHeight) > capacity() + FIT_EPSILON
        ? getSplittable(nextIndex)
        : null;
      if (splittable && splittable.count >= splittable.orphans + splittable.widows) {
        height += nextHeight - splittable.height +
          flowTextPieceHeight(splittable.entry, splittable.height, 0, splittable.orphans - 1);
        break;
      }
      height += nextHeight;

      // Preserve the baseline's left-to-right lookahead sum, but once that
      // exact placement expression is already over a finite page's capacity,
      // non-negative later measurements cannot make the move decision false.
      if (
        stopEarly &&
        currentHeight + (ownHeight + height) > capacity()
      ) break;

      priorIndex = nextIndex;
    }

    return height;
  };

  const startNextChunk = () => {
    if (currentHasContent()) {
      chunks.push({ indexes: [], keys: [] });
      currentHeight = 0;
    }
  };

  const placeRun = (start, end) => {
    const chunk = currentChunk();
    for (let index = start; index <= end; index += 1) {
      chunk.indexes.push(index);
      chunk.keys.push(keys[at(index)] ?? String(at(index)));
    }
  };
  // `meta.growSheet` / `headerGroupGrows`: the item, or the group's run, is placed whole after what
  // the page holds, and the sheet grows by what it needs beyond the page's region. The sheet ends
  // with it.
  const placeGrowingRun = (start, end, runHeight) => {
    placeRun(start, end);
    currentChunk().growth = currentHeight + runHeight - capacity();
    chunks.push({ indexes: [], keys: [] });
    currentHeight = 0;
  };

  const addUnplaceableItem = (index, height, requiredHeight) => {
    const key = keys[at(index)] ?? String(at(index));
    if (growsSheet(index)) {
      placeGrowingRun(index, index, requiredHeight);
      return;
    }
    const groupKey = getHeaderGroupKey(index) ?? undefined;
    const headerHeight = groupKey && needsGroupHeader(index, null)
      ? getHeaderHeight(groupKey)
      : 0;
    const unplaceable = {
      index,
      key,
      height,
      headerHeight,
      requiredHeight,
      // The region of the page it renders on, which it is scaled to fit.
      availableHeight: capacity(),
      groupKey,
      reason: headerHeight > 0 ? 'item-with-header-too-tall' : 'item-too-tall',
    };

    // A discrete chunk of its own keeps virtual-page expansion finite; the item
    // renders there scaled to fit the region (flow-render.tsx).
    currentChunk().unplaceable = unplaceable;
    onUnplaceableItem?.(unplaceable);
    chunks.push({ indexes: [], keys: [] });
    currentHeight = 0;
  };

  /** Whether the item-level rules below place the item whole on the page being filled. */
  const placesWhole = (index, meta) => {
    const hasContent = currentHasContent();
    const ownHeight = getItemHeightWithHeader(index, currentLastIndex());
    if (ownHeight > capacity() - currentHeight) return false;
    if (!hasContent) return true;
    const keepWithNextHeight = getKeepWithNextHeight(index, getKeepWithNextCount(meta.keepWithNext), {
      currentHeight,
      ownHeight,
      stopEarly: Number.isFinite(capacity()),
    });
    return currentHeight + ownHeight + keepWithNextHeight <= capacity();
  };

  /**
   * Place an item that may split between its lines. Whole when it fits; otherwise the largest
   * piece the room holds that leaves `orphans` lines at the bottom of this page and `widows` at the
   * top of the next, on as many pages as it takes. A page that already has content gives up its
   * room rather than break those rules; an empty page splits as far as it can, so every piece
   * holds at least one line and the plan always progresses.
   */
  const placeSplittableItem = (index, key, meta, splittable) => {
    const { entry, height, count, orphans, widows } = splittable;
    const piece = (first, last) => flowTextPieceHeight(entry, height, first, last);
    // The largest last line in first..maxLast whose piece fits `room`, or first - 1.
    const largestFitting = (first, maxLast, room) => {
      let low = first;
      let high = maxLast;
      let found = first - 1;
      while (low <= high) {
        const middle = (low + high) >> 1;
        if (piece(first, middle) <= room + FIT_EPSILON) {
          found = middle;
          low = middle + 1;
        } else {
          high = middle - 1;
        }
      }
      return found;
    };
    const place = (first, last, pieceHeight) => {
      const chunk = currentChunk();
      chunk.indexes.push(index);
      chunk.keys.push(key);
      currentHeight += pieceHeight;
      if (first === 0 && last === count - 1) return;
      let pieces = chunkPieces.get(chunk);
      if (!pieces) {
        pieces = new Map();
        chunkPieces.set(chunk, pieces);
      }
      pieces.set(index, [first, last]);
    };

    let first = 0;
    for (;;) {
      if (metrics) metrics.scannedItems += 1;
      decideReserve(index, first, splittable);
      const hasContent = currentHasContent();
      const header = first === 0
        ? getHeaderHeightFor(index, currentLastIndex())
        : getContinuationHeaderHeight(index);
      const room = capacity() - currentHeight;
      const rest = (first === 0 ? height : piece(first, count - 1)) + header;

      if (rest <= room + FIT_EPSILON) {
        // The rest fits: it is the last piece, so `keepWithNext` is evaluated for it. Only the
        // whole item can share a page with content before it; a later piece starts its page.
        if (hasContent) {
          const keepWithNextHeight = getKeepWithNextHeight(index, getKeepWithNextCount(meta.keepWithNext), {
            currentHeight,
            ownHeight: rest,
            stopEarly: Number.isFinite(capacity()),
          });
          if (currentHeight + rest + keepWithNextHeight > capacity() + FIT_EPSILON) {
            // Its last `widows` lines go on with what it keeps with; whole if it cannot split.
            const last = count - 1 - widows;
            if (last - first + 1 >= orphans) {
              place(first, last, piece(first, last) + header);
              startNextChunk();
              first = last + 1;
            } else {
              startNextChunk();
            }
            continue;
          }
        }
        place(first, count - 1, rest);
        return;
      }

      const fitting = largestFitting(first, count - 2, room - header);
      const last = Math.min(fitting, count - 1 - widows);
      if (last >= first && last - first + 1 >= orphans) {
        place(first, last, piece(first, last) + header);
      } else if (hasContent) {
        startNextChunk();
        continue;
      } else {
        // An empty page that cannot honor orphans and widows: split as far as it holds.
        const forced = Math.max(first, fitting);
        place(first, forced, piece(first, forced) + header);
        if (forced >= count - 1) return;
        first = forced + 1;
        startNextChunk();
        continue;
      }
      first = last + 1;
      startNextChunk();
    }
  };

  for (let index = 0; index < itemCount; index += 1) {
    // `maxChunks` chunks are closed as soon as one more has been opened.
    if (maxChunks && chunks.length > maxChunks) break;
    if (metrics) metrics.scannedItems += 1;
    const meta = metas[at(index)] ?? {};
    const height = finitePositive(heights[at(index)]);
    const key = keys[at(index)] ?? String(at(index));

    if (meta.breakBefore) {
      startNextChunk();
    }

    const avoidBreakGroupKey = getAvoidBreakGroupKey(index);
    const previousAvoidBreakGroupKey = index > 0 ? getAvoidBreakGroupKey(index - 1) : null;
    if (
      avoidBreakGroupKey &&
      avoidBreakGroupKey !== previousAvoidBreakGroupKey &&
      currentHasContent() &&
      currentHeight + getAvoidBreakGroupHeight(index, avoidBreakGroupKey, currentLastIndex()) > capacity()
    ) {
      // If the group cannot fit on an empty page we intentionally fall through
      // to normal row-level continuation below instead of creating a blank page.
      startNextChunk();
    }

    decideReserve(index);

    // `headerGroupGrows`: the group's run is one unit. It fits the room left, or moves whole to a
    // page that holds it, or, taller than any page, starts right under what precedes it and grows
    // the sheet. Nothing in it splits, and its header is placed once.
    const runEnd = growingRunEnd(index);
    if (runEnd >= 0) {
      let runHeight = growingRunHeight(index, runEnd, currentLastIndex());
      if (!tallerThanAnyPage(runHeight) && currentHasContent() && currentHeight + runHeight > capacity()) {
        startNextChunk();
        decideReserve(index);
        runHeight = growingRunHeight(index, runEnd, null);
      }
      if (currentHeight + runHeight > capacity()) {
        placeGrowingRun(index, runEnd, runHeight);
      } else {
        placeRun(index, runEnd);
        currentHeight += runHeight;
      }
      if ((metas[at(runEnd)] ?? {}).breakAfter && runEnd < itemCount - 1) startNextChunk();
      index = runEnd;
      continue;
    }

    // An item placed whole on this page plans exactly as without line metrics; one that would move
    // on (or not fit any page) may split instead.
    const splittable = hasLines(index) && !placesWhole(index, meta) ? getSplittable(index) : null;
    if (splittable) {
      placeSplittableItem(index, key, meta, splittable);
      if (meta.breakAfter && index < itemCount - 1) {
        startNextChunk();
      }
      continue;
    }

    let previousIndex = currentLastIndex();
    let ownHeight = getItemHeightWithHeader(index, previousIndex);

    // `meta.growSheet`: no page holds it, so it starts right under what precedes it.
    if (growsSheet(index) && tallerThanAnyPage(ownHeight)) {
      placeGrowingRun(index, index, ownHeight);
      continue;
    }

    // A page boundary can add a repeated group header. Recalculate after moving
    // so a row is never admitted based on the previous page's header state.
    if (currentHasContent() && ownHeight > capacity() - currentHeight) {
      startNextChunk();
      previousIndex = null;
      decideReserve(index);
      ownHeight = getItemHeightWithHeader(index, previousIndex);
    }

    if (ownHeight > capacity()) {
      addUnplaceableItem(index, height, ownHeight);
      continue;
    }

    const hasCurrentContent = currentHasContent();
    // `keepWithNext` only decides whether to move an item away from an
    // existing fragment. On an empty fragment it cannot change the result, so
    // avoid scanning a potentially large lookahead range that is discarded.
    const keepWithNextHeight = hasCurrentContent
      ? getKeepWithNextHeight(index, getKeepWithNextCount(meta.keepWithNext), {
        currentHeight,
        ownHeight,
        stopEarly: Number.isFinite(capacity()),
      })
      : 0;
    const requiredHeight = ownHeight + keepWithNextHeight;
    if (hasCurrentContent && currentHeight + requiredHeight > capacity()) {
      startNextChunk();
      previousIndex = null;
      decideReserve(index);
      ownHeight = getItemHeightWithHeader(index, previousIndex);

      if (ownHeight > capacity()) {
        addUnplaceableItem(index, height, ownHeight);
        continue;
      }
    }

    currentChunk().indexes.push(index);
    currentChunk().keys.push(key);
    currentHeight += ownHeight;

    if (meta.breakAfter && index < itemCount - 1) {
      startNextChunk();
    }
  }

  const allPopulatedChunks = chunks.filter((chunk) => (
    chunk.indexes.length > 0 || Boolean(chunk.unplaceable)
  ));
  if (!allPopulatedChunks.length) {
    if (metrics && !maxChunks) metrics.pages = 1;
    return [{ indexes: [], keys: [] }];
  }
  const populatedChunks = maxChunks
    ? allPopulatedChunks.slice(0, maxChunks)
    : allPopulatedChunks;
  if (metrics && !maxChunks) metrics.pages = populatedChunks.length;

  const splitsByChunk = buildFlowTextSplits(populatedChunks, chunkPieces, (index) => getSplittable(index).entry);

  return populatedChunks.map((chunk) => {
    if (!chunk.indexes.length) return chunk;
    const pieces = chunkPieces.get(chunk);

    const groupHeaders = [];
    for (let position = 0; position < chunk.indexes.length; position += 1) {
      const itemIndex = chunk.indexes[position];
      const groupKey = getHeaderGroupKey(itemIndex);
      if (!groupKey) continue;
      // A split item's continuation piece opens its page and resumes its own group.
      if (position === 0 && pieces?.get(itemIndex)?.[0] > 0) {
        if (shouldRepeatHeader(groupKey)) groupHeaders.push({ groupKey, itemIndex, isContinuation: true });
        continue;
      }
      const previousIndex = position > 0 ? chunk.indexes[position - 1] : null;
      if (!needsGroupHeader(itemIndex, previousIndex)) continue;

      const previousSourceGroupKey = itemIndex > 0 ? getHeaderGroupKey(itemIndex - 1) : null;
      groupHeaders.push({
        groupKey,
        itemIndex,
        isContinuation: previousSourceGroupKey === groupKey,
      });
    }

    const splits = splitsByChunk.get(chunk);
    if (!groupHeaders.length && !splits) return chunk;
    return {
      ...chunk,
      ...(groupHeaders.length ? { groupHeaders } : {}),
      ...(splits ? { splits } : {}),
    };
  });
}

/**
 * Where the piece's lines end with a hyphen the browser drew: the offset each such line's
 * successor starts at (the piece's own end included). A piece renders them as soft hyphens, so its
 * slice breaks exactly where the measured text broke, and ends with a hyphen only where one showed.
 */
function hyphenBreaks(lines, first, last, isLastPiece) {
  const breaks = [];
  for (let line = first; line <= last; line += 1) {
    if (!lines[line].hyphen || (line === lines.length - 1)) continue;
    if (line === last && isLastPiece) continue;
    breaks.push(lines[line + 1].start);
  }
  return breaks.length ? { hyphens: breaks } : {};
}

/**
 * Number the pieces of every split item (`part` of `parts`, 0-based) and turn their line ranges
 * into text offsets: `from` is where the piece's first line starts, `to` where the next piece's
 * starts (`end` for the last piece), so the pieces' text concatenates to the item's.
 */
function buildFlowTextSplits(chunks, chunkPieces, getEntry) {
  const splitsByChunk = new Map();
  if (!chunkPieces.size) return splitsByChunk;
  const piecesByItem = new Map();
  for (const chunk of chunks) {
    for (const [index, range] of chunkPieces.get(chunk) ?? []) {
      let pieces = piecesByItem.get(index);
      if (!pieces) {
        pieces = [];
        piecesByItem.set(index, pieces);
      }
      pieces.push({ chunk, range });
    }
  }
  for (const [index, pieces] of piecesByItem) {
    const entry = getEntry(index);
    const { lines } = entry;
    pieces.forEach(({ chunk, range: [first, last] }, part) => {
      let splits = splitsByChunk.get(chunk);
      if (!splits) {
        splits = {};
        splitsByChunk.set(chunk, splits);
      }
      splits[index] = {
        part,
        parts: pieces.length,
        from: part === 0 ? 0 : lines[first].start,
        to: part === pieces.length - 1 ? entry.end : lines[last + 1].start,
        ...(entry.justify ? { justify: true } : {}),
        // The planned height of the piece's lines: a visible piece checks it rendered no taller.
        textHeight: lines[last].bottom - lines[first].top,
        ...hyphenBreaks(lines, first, last, part === pieces.length - 1),
      };
    });
  }
  return splitsByChunk;
}

function layoutChunkHeight(chunk, heights, headerGroupHeights) {
  const itemHeight = (chunk.indexes ?? []).reduce(
    (sum, index) => sum + finitePositive(heights[index]),
    0
  );
  const headerHeight = (chunk.groupHeaders ?? []).reduce(
    (sum, header) => sum + finitePositive(headerGroupHeights[header.groupKey]),
    0
  );
  return itemHeight + headerHeight;
}

function trackFlowPlanInput(input, columnGroupId, columnId) {
  if (!columnGroupId || !columnId) return input;
  return {
    ...input,
    headerGroupHeights:
      input.columnHeaderGroupHeights?.[columnGroupId]?.[columnId] ??
      input.headerGroupHeights,
    headerGroupRepeats:
      input.columnHeaderGroupRepeats?.[columnGroupId]?.[columnId] ??
      input.headerGroupRepeats,
  };
}

function restoreGlobalChunk(
  chunk,
  indexes,
  offset,
  columnId,
  headerGroupKeys,
  previousSourceIndex
) {
  const globalIndex = (localIndex) => indexes[offset + localIndex];
  const restored = {
    indexes: (chunk.indexes ?? []).map(globalIndex).filter(Number.isInteger),
    keys: [...(chunk.keys ?? [])],
    ...(previousSourceIndex !== undefined ? { previousSourceIndex } : {}),
  };
  if (chunk.groupHeaders?.length) {
    restored.groupHeaders = chunk.groupHeaders.map((header) => ({
      ...header,
      itemIndex: globalIndex(header.itemIndex),
      isContinuation:
        header.isContinuation ||
        (
          header.itemIndex === 0 &&
          previousSourceIndex !== undefined &&
          headerGroupKeys?.[previousSourceIndex] === header.groupKey
        ),
    }));
  }
  if (chunk.unplaceable) {
    restored.unplaceable = {
      ...chunk.unplaceable,
      index: globalIndex(chunk.unplaceable.index),
      ...(columnId ? { columnId } : {}),
    };
  }
  if (chunk.growth > 0) restored.growth = chunk.growth;
  return restored;
}

/**
 * Paginate the first page's worth of `indexes` from `offset` onwards.
 *
 * The window is passed by reference: the leaf chunker reads the caller's arrays
 * through it and stops as soon as one chunk is closed, so laying out a page
 * costs what that page holds rather than what the rest of the document holds.
 */
function firstChunkForIndexes(
  input,
  indexes,
  offset,
  availableHeight,
  columnGroupId,
  columnId,
  previousSourceIndex,
  // `meta.growSheet` in a sequential run: the full page an item could still move to.
  growPageHeight
) {
  if (offset >= indexes.length) {
    return {
      chunk: { indexes: [], keys: [] },
      consumed: 0,
      height: 0,
    };
  }
  const trackInput = trackFlowPlanInput(input, columnGroupId, columnId);
  if (input.metrics) input.metrics.chunkerCalls += 1;
  const localChunks = distributeFlowItems({
    heights: input.heights,
    keys: input.keys,
    metas: input.metas,
    headerGroupKeys: input.headerGroupKeys,
    headerGroupHeights: trackInput.headerGroupHeights,
    headerGroupRepeats: trackInput.headerGroupRepeats,
    headerGroupGrows: input.headerGroupGrows,
    previousHeaderGroupKey: previousSourceIndex === undefined
      ? undefined
      : input.headerGroupKeys?.[previousSourceIndex],
    availableHeight,
    window: { indexes, offset },
    maxChunks: 1,
    // Only a sequential run's sheet grows; a column group keeps the page's size.
    ...(growPageHeight ? { continuationHeight: growPageHeight } : { fixedSheets: true }),
    metrics: input.metrics,
  });
  const localChunk = localChunks[0] ?? { indexes: [], keys: [] };
  const chunk = restoreGlobalChunk(
    localChunk,
    indexes,
    offset,
    columnId,
    trackInput.headerGroupKeys,
    previousSourceIndex
  );
  const consumed = chunk.unplaceable ? 1 : chunk.indexes.length;
  return {
    chunk,
    consumed,
    height: layoutChunkHeight(
      chunk,
      input.heights ?? [],
      trackInput.headerGroupHeights ?? {}
    ),
  };
}

/**
 * The columns a flowing column group draws, as a `columns` node: ids `column-1` … `column-<n>`,
 * its whole text in the first (where measurement lays it out) and none in the others.
 */
export function flowingColumnsView(node) {
  const count = Number.isInteger(node?.columns) && node.columns > 0 ? node.columns : 1;
  return {
    kind: 'columns',
    id: String(node?.id ?? 'columns'),
    columns: Array.from({ length: count }, (_, index) => ({
      id: `column-${index + 1}`,
      indexes: index === 0 ? [...(node?.indexes ?? [])] : [],
    })),
  };
}

export function validateFlowColumnLayout({ nodes = [], itemCount = 0, flowId } = {}) {
  const groupIds = new Set();
  const seenIndexes = new Set();
  const fail = (message) => {
    throw new TypeError(`[uhuu-components] Invalid Static.FlowColumns${flowId ? ` "${flowId}"` : ''} layout: ${message}`);
  };
  const claimIndex = (index, location) => {
    if (!Number.isInteger(index) || index < 0 || index >= itemCount) {
      fail(`${location} references out-of-range item index ${String(index)}.`);
    }
    if (seenIndexes.has(index)) fail(`item index ${index} occurs more than once.`);
    seenIndexes.add(index);
  };

  nodes.forEach((node, nodeIndex) => {
    if (!node || (node.kind !== 'item' && node.kind !== 'columns' && node.kind !== 'flowingColumns')) {
      fail(`node ${nodeIndex} has an unsupported kind.`);
    }
    if (node.kind === 'item') {
      claimIndex(node.index, `node ${nodeIndex}`);
      return;
    }
    if (typeof node.id !== 'string' || !node.id) fail(`column group ${nodeIndex} needs a stable id.`);
    if (groupIds.has(node.id)) fail(`column group id "${node.id}" occurs more than once.`);
    groupIds.add(node.id);
    if (node.kind === 'flowingColumns') {
      if (!Number.isInteger(node.columns) || node.columns < 1) {
        fail(`flowing column group "${node.id}" has columns ${JSON.stringify(node.columns)}; columns is how many, 1 or more.`);
      }
      if (node.columnFill !== undefined && node.columnFill !== 'balance' && node.columnFill !== 'auto') {
        fail(`flowing column group "${node.id}" has columnFill ${JSON.stringify(node.columnFill)}; it is "balance" or "auto".`);
      }
      (node.indexes ?? []).forEach((index) => claimIndex(index, `flowing column group "${node.id}"`));
      return;
    }
    const columnIds = new Set();
    (node.columns ?? []).forEach((column, columnIndex) => {
      if (!column || typeof column.id !== 'string' || !column.id) {
        fail(`column ${columnIndex} in group "${node.id}" needs a stable id.`);
      }
      if (columnIds.has(column.id)) {
        fail(`column id "${column.id}" occurs more than once in group "${node.id}".`);
      }
      columnIds.add(column.id);
      (column.indexes ?? []).forEach((index) => {
        claimIndex(index, `column "${column.id}" in group "${node.id}"`);
      });
    });
  });

  for (let index = 0; index < itemCount; index += 1) {
    if (!seenIndexes.has(index)) fail(`item index ${index} is omitted.`);
  }
  return true;
}

/**
 * Whether an in-page attempt should be retried on a fresh page:
 *   `'no'`      — keep it;
 *   `'move'`    — move unconditionally (a row a full page could still hold);
 *   `'compare'` — move only if a fresh page consumes more;
 *   `'unless-grown'` — move only if a fresh page holds it without growing (`growSheet`).
 *
 * The one owner of the rule for every track: a sequential run, an independent column and a
 * flowing column (`placeFlowingColumns`' `defersToFreshSheet`) all ask here. A protected start is
 * retried only when the attempt strands it: a `keepWithNext` item left with no more than what it
 * keeps (the leaf chunker places it on an empty page regardless), or an `avoidBreakInside` group
 * that goes on past the attempt. A run that holds its keep, or the rest, fills the room it is in.
 *
 * Only `'compare'` and `'unless-grown'` need the fresh attempt to exist, so unconstrained content —
 * the overwhelming majority — never pays for a speculative second pagination.
 */
function freshPageRetryVerdict(input, indexes, offset, attempt, fullPageHeight) {
  const unplaceableRequiredHeight = finitePositive(attempt.chunk.unplaceable?.requiredHeight);
  if (unplaceableRequiredHeight > 0 && unplaceableRequiredHeight <= fullPageHeight) return 'move';
  // `growSheet`: a run that grows this sheet moves when a fresh page holds it without growing.
  if (attempt.chunk.growth > 0) return 'unless-grown';
  const firstIndex = indexes[offset];
  if (firstIndex === undefined) return 'no';
  const next = offset + attempt.consumed;
  if (next >= indexes.length) return 'no';
  const meta = input.metas?.[firstIndex] ?? {};
  const nextMeta = input.metas?.[indexes[next]] ?? {};
  const keepCount = getKeepWithNextCount(meta.keepWithNext);
  const stranded = (keepCount > 0 && attempt.consumed <= keepCount) ||
    Boolean(meta.avoidBreakInside && meta.groupKey && nextMeta.avoidBreakInside && nextMeta.groupKey === meta.groupKey);
  return stranded ? 'compare' : 'no';
}

function layoutPageHasContent(page) {
  return Boolean(page.layout?.length || page.unplaceable);
}

/**
 * Plan a one-level Flow layout: ordinary story items remain sequential, while a
 * `columns` node advances each of its columns independently. A column group may
 * begin in the remaining space on a page; if any leading item only fails because
 * that remainder is short (`freshPageRetryVerdict`: it strands a protected run, or a fresh page
 * holds an item this one cannot), the whole group moves to a fresh page before retrying.
 *
 * The leaf chunking contract is still `distributeFlowItems`. This coordinator
 * owns only the bounded sequential/parallel relationship, so keep/break/header
 * behavior stays identical between normal Flow and FlowColumns. `meta.growSheet`
 * grows a page for a sequential item as in Flow; a column group keeps the page's
 * size, and the page's `growth` is the item's.
 */
export function distributeFlowColumns({
  nodes = [],
  heights = [],
  keys = [],
  metas = [],
  availableHeight = 0,
  /** The region of every page after the first; defaults to `availableHeight`. */
  continuationHeight,
  headerGroupKeys = [],
  headerGroupHeights = {},
  headerGroupRepeats = {},
  headerGroupGrows = {},
  columnHeaderGroupHeights = {},
  columnHeaderGroupRepeats = {},
  onUnplaceableItem,
  /** Optional `createFlowPlanMetrics()` object, filled in as the plan is built. */
  metrics,
} = {}) {
  validateFlowColumnLayout({ nodes, itemCount: heights.length });
  const normalizedAvailableHeight = finitePositive(availableHeight) || Number.POSITIVE_INFINITY;
  const normalizedContinuationHeight = finitePositive(continuationHeight) || normalizedAvailableHeight;
  const input = {
    heights,
    keys,
    metas,
    headerGroupKeys,
    headerGroupHeights,
    headerGroupRepeats,
    headerGroupGrows,
    columnHeaderGroupHeights,
    columnHeaderGroupRepeats,
    metrics,
  };
  const pages = [{ indexes: [], keys: [], layout: [] }];
  let usedHeight = 0;
  const currentPage = () => pages[pages.length - 1];
  // The region of the page being filled, and of the page a fresh-page retry starts: always a
  // continuation page, since a retry is only considered on a page that already has content.
  const currentCapacity = () => (pages.length > 1 ? normalizedContinuationHeight : normalizedAvailableHeight);
  const nextPageCapacity = normalizedContinuationHeight;
  // `meta.growSheet` / `headerGroupGrows` (the screen view): a sequential run's sheet may grow, as
  // in Static.Flow; a column group keeps the page's size. Without them every call is exactly as before.
  const growPageHeight = metas.some((meta) => meta?.growSheet) || Object.values(headerGroupGrows).some(Boolean)
    ? nextPageCapacity
    : undefined;
  const startPage = () => {
    if (!layoutPageHasContent(currentPage())) return;
    pages.push({ indexes: [], keys: [], layout: [] });
    usedHeight = 0;
  };
  const addChunkIndexes = (chunk) => {
    currentPage().indexes.push(...(chunk.indexes ?? []));
    currentPage().keys.push(...(chunk.keys ?? []));
    if (!currentPage().unplaceable && chunk.unplaceable) {
      currentPage().unplaceable = chunk.unplaceable;
    }
    if (chunk.unplaceable) onUnplaceableItem?.(chunk.unplaceable);
  };

  /**
   * A flowing column group (`kind: 'flowingColumns'`): one list, its `indexes`, read down the first
   * column, then the next, then on into the first column of the next sheet. Every column of
   * a sheet has the room the group starts in; items move whole. The group's last sheet is balanced
   * (`columnFill: 'balance'`, the default, as CSS `column-fill`): its columns get the least height
   * that still holds the rest. `columnFill: 'auto'` fills the columns in order there too.
   */
  const placeFlowingColumns = (node) => {
    const groupId = String(node.id ?? 'columns');
    const columnIds = flowingColumnsView(node).columns.map((column) => column.id);
    const flowIndexes = (node.indexes ?? []).filter(
      (index) => Number.isInteger(index) && index >= 0 && index < heights.length
    );
    if (!flowIndexes.length || !columnIds.length) return;
    const emptyChunk = () => ({ indexes: [], keys: [] });
    // Measurement lays every item out in the first column, so its group headers are read there.
    const pourColumn = (cursor, capacity, columnId) => {
      const attempt = firstChunkForIndexes(
        input,
        flowIndexes,
        cursor,
        capacity,
        groupId,
        columnIds[0],
        cursor > 0 ? flowIndexes[cursor - 1] : undefined
      );
      if (attempt.chunk.unplaceable) attempt.chunk.unplaceable.columnId = columnId;
      return attempt;
    };
    // A column that strands a protected run (`keepWithNext`, an `avoidBreakInside` group), where a
    // fresh sheet's first column holds more, is left for that sheet; so is an item too tall for
    // this column that a fresh sheet holds. The rule is `freshPageRetryVerdict`'s, as for a
    // sequential run; a column group never grows its sheet, so `'unless-grown'` does not occur.
    const defersToFreshSheet = (cursor, attempt) => {
      const verdict = freshPageRetryVerdict(input, flowIndexes, cursor, attempt, nextPageCapacity);
      if (verdict === 'no') return false;
      if (verdict === 'move') return true;
      if (metrics) metrics.freshPageAttempts += 1;
      return pourColumn(cursor, nextPageCapacity, columnIds[0]).consumed > attempt.consumed;
    };
    // Fill the columns of one sheet from `start`, each `capacity` tall.
    const pour = (start, capacity) => {
      const attempts = [];
      let cursor = start;
      let stopped = false;
      columnIds.forEach((columnId, columnIndex) => {
        if (stopped || cursor >= flowIndexes.length) return;
        // A forced break is a sheet break: the columns after it stay empty.
        if (columnIndex > 0 && metas[flowIndexes[cursor]]?.breakBefore) {
          stopped = true;
          return;
        }
        const attempt = pourColumn(cursor, capacity, columnId);
        if (columnIndex > 0 && defersToFreshSheet(cursor, attempt)) {
          stopped = true;
          return;
        }
        attempts[columnIndex] = attempt;
        cursor += attempt.consumed;
        const lastIndex = attempt.chunk.indexes?.at(-1) ?? attempt.chunk.unplaceable?.index;
        if (attempt.chunk.unplaceable || (lastIndex !== undefined && metas[lastIndex]?.breakAfter)) stopped = true;
      });
      return { attempts, cursor, stopped };
    };
    const pouredHeight = (poured) => Math.max(0, ...poured.attempts.filter(Boolean).map((attempt) => attempt.height));
    const holdsRest = (poured) => !poured.stopped && poured.cursor >= flowIndexes.length;
    // The last sheet: the least column height (to half a pixel) at which the rest still fits.
    const balance = (start, filled) => {
      if (node.columnFill === 'auto' || !holdsRest(filled) || columnIds.length < 2) return filled;
      let total = 0;
      for (let cursor = start; cursor < flowIndexes.length; cursor += 1) total += finitePositive(heights[flowIndexes[cursor]]);
      let best = filled;
      let low = total / columnIds.length;
      let high = pouredHeight(filled);
      while (high - low > 0.5) {
        const middle = (low + high) / 2;
        const trial = pour(start, middle);
        if (holdsRest(trial)) {
          best = trial;
          high = Math.min(middle, pouredHeight(trial));
        } else {
          low = middle;
        }
      }
      return best;
    };

    let cursor = 0;
    while (cursor < flowIndexes.length) {
      if (currentCapacity() - usedHeight <= 0 && layoutPageHasContent(currentPage())) startPage();
      if (metas[flowIndexes[cursor]]?.breakBefore && layoutPageHasContent(currentPage())) startPage();
      let capacity = currentCapacity() - usedHeight;
      // Under other content, the whole group moves when its first column is better off on a fresh sheet.
      if (layoutPageHasContent(currentPage()) && defersToFreshSheet(cursor, pourColumn(cursor, capacity, columnIds[0]))) {
        startPage();
        capacity = currentCapacity();
      }
      const poured = balance(cursor, pour(cursor, capacity));
      if (poured.cursor === cursor) {
        throw new TypeError(
          `[uhuu-components] Static.FlowColumns made no pagination progress in flowing column group "${groupId}".`
        );
      }
      const columnChunks = columnIds.map((id, columnIndex) => ({
        id,
        chunk: poured.attempts[columnIndex]?.chunk ?? emptyChunk(),
      }));
      currentPage().layout.push({ kind: 'columns', id: groupId, columns: columnChunks });
      for (const { chunk } of columnChunks) addChunkIndexes(chunk);
      usedHeight += pouredHeight(poured);
      cursor = poured.cursor;
      if (cursor < flowIndexes.length || poured.stopped) startPage();
    }
  };

  for (let nodeIndex = 0; nodeIndex < nodes.length; nodeIndex += 1) {
    const node = nodes[nodeIndex];
    if (!node || (node.kind !== 'item' && node.kind !== 'columns' && node.kind !== 'flowingColumns')) continue;

    if (node.kind === 'item') {
      const sequence = [];
      let sequenceNodeIndex = nodeIndex;
      while (sequenceNodeIndex < nodes.length && nodes[sequenceNodeIndex]?.kind === 'item') {
        const index = Number(nodes[sequenceNodeIndex].index);
        if (Number.isInteger(index) && index >= 0 && index < heights.length) sequence.push(index);
        sequenceNodeIndex += 1;
      }
      nodeIndex = sequenceNodeIndex - 1;
      let cursor = 0;
      while (cursor < sequence.length) {
        if (currentCapacity() - usedHeight <= 0 && layoutPageHasContent(currentPage())) {
          startPage();
        }
        const firstIndex = sequence[cursor];
        if (metas[firstIndex]?.breakBefore && layoutPageHasContent(currentPage())) startPage();

        const previousSourceIndex = cursor > 0 ? sequence[cursor - 1] : undefined;
        let result = firstChunkForIndexes(
          input,
          sequence,
          cursor,
          currentCapacity() - usedHeight,
          undefined,
          undefined,
          previousSourceIndex,
          growPageHeight
        );
        if (layoutPageHasContent(currentPage())) {
          const verdict = freshPageRetryVerdict(
            input,
            sequence,
            cursor,
            result,
            nextPageCapacity
          );
          if (verdict !== 'no') {
            if (metrics) metrics.freshPageAttempts += 1;
            const freshResult = firstChunkForIndexes(
              input,
              sequence,
              cursor,
              nextPageCapacity,
              undefined,
              undefined,
              previousSourceIndex,
              growPageHeight
            );
            const better = verdict === 'unless-grown'
              ? !(freshResult.chunk.growth > 0)
              : freshResult.consumed > result.consumed;
            if (verdict === 'move' || better) {
              startPage();
              result = freshResult;
            }
          }
        }

        currentPage().layout.push({ kind: 'items', chunk: result.chunk });
        addChunkIndexes(result.chunk);
        usedHeight += result.height;
        cursor += result.consumed;
        if (result.consumed === 0) cursor += 1;
        // The sheet grows to hold the item it ends with.
        if (result.chunk.growth > 0) currentPage().growth = result.chunk.growth;

        const lastIndex = result.chunk.indexes?.at(-1) ?? result.chunk.unplaceable?.index;
        const hasRemaining = cursor < sequence.length;
        if (
          hasRemaining ||
          result.chunk.unplaceable ||
          result.chunk.growth > 0 ||
          (lastIndex !== undefined && metas[lastIndex]?.breakAfter)
        ) startPage();
      }
      continue;
    }

    if (node.kind === 'flowingColumns') {
      placeFlowingColumns(node);
      continue;
    }

    const columns = (node.columns ?? [])
      .map((column) => ({
        id: String(column?.id ?? ''),
        indexes: (column?.indexes ?? []).filter(
          (index) => Number.isInteger(index) && index >= 0 && index < heights.length
        ),
        cursor: 0,
      }))
      .filter((column) => column.id && column.indexes.length);
    if (!columns.length) continue;

    while (columns.some((column) => column.cursor < column.indexes.length)) {
      if (currentCapacity() - usedHeight <= 0 && layoutPageHasContent(currentPage())) {
        startPage();
      }
      const startsWithForcedBreak = columns.some((column) => {
        const index = column.indexes[column.cursor];
        return index !== undefined && metas[index]?.breakBefore;
      });
      if (startsWithForcedBreak && layoutPageHasContent(currentPage())) startPage();

      const capacity = currentCapacity() - usedHeight;
      let attempts = columns.map((column) => firstChunkForIndexes(
        input,
        column.indexes,
        column.cursor,
        capacity,
        node.id,
        column.id,
        column.cursor > 0 ? column.indexes[column.cursor - 1] : undefined
      ));
      let freshAttempts;
      const ensureFreshAttempts = () => (freshAttempts ??= columns.map((candidate) => {
        if (metrics) metrics.freshPageAttempts += 1;
        return firstChunkForIndexes(
          input,
          candidate.indexes,
          candidate.cursor,
          nextPageCapacity,
          node.id,
          candidate.id,
          candidate.cursor > 0 ? candidate.indexes[candidate.cursor - 1] : undefined
        );
      }));
      // `some` short-circuits exactly as before; the fresh attempts are now
      // materialised only once a column actually needs them to decide.
      const shouldMoveWholeGroup = layoutPageHasContent(currentPage()) && columns.some((column, columnIndex) => {
        const verdict = freshPageRetryVerdict(
          input,
          column.indexes,
          column.cursor,
          attempts[columnIndex],
          nextPageCapacity
        );
        if (verdict === 'no') return false;
        if (verdict === 'move') return true;
        return ensureFreshAttempts()[columnIndex].consumed > attempts[columnIndex].consumed;
      });
      if (shouldMoveWholeGroup) {
        startPage();
        attempts = ensureFreshAttempts();
      }

      if (!attempts.some((attempt) => attempt.consumed > 0)) {
        const stalled = columns.find((column) => column.cursor < column.indexes.length);
        throw new TypeError(
          `[uhuu-components] Static.FlowColumns made no pagination progress` +
          `${stalled ? ` in column "${stalled.id}"` : ''}.`
        );
      }

      const columnChunks = columns.map((column, columnIndex) => ({
        id: column.id,
        chunk: attempts[columnIndex].chunk,
      }));
      currentPage().layout.push({
        kind: 'columns',
        id: String(node.id ?? 'columns'),
        columns: columnChunks,
      });
      for (const { chunk } of columnChunks) addChunkIndexes(chunk);

      const groupHeight = Math.max(0, ...attempts.map((attempt) => attempt.height));
      usedHeight += groupHeight;
      columns.forEach((column, columnIndex) => {
        column.cursor += attempts[columnIndex].consumed;
      });

      const hasRemaining = columns.some((column) => column.cursor < column.indexes.length);
      const forcedBreakAfter = attempts.some((attempt) => {
        const lastIndex = attempt.chunk.indexes?.at(-1) ?? attempt.chunk.unplaceable?.index;
        return lastIndex !== undefined && metas[lastIndex]?.breakAfter;
      });
      const hasUnplaceable = attempts.some((attempt) => Boolean(attempt.chunk.unplaceable));
      if (hasRemaining || forcedBreakAfter || hasUnplaceable) startPage();
    }
  }

  const populatedPages = pages.filter(layoutPageHasContent);
  if (!populatedPages.length) {
    if (metrics) metrics.pages = 1;
    return [{ indexes: [], keys: [], layout: [] }];
  }
  if (metrics) metrics.pages = populatedPages.length;
  return populatedPages;
}
