import * as React from 'react';
import { getFlowFragmentState } from './flow-core';
import { StaticFlowContext } from './flow-context';
import { FlowTextSplitContext } from './flow-text';
import { useView } from './view';
import { serializeLineCount } from './flow-measure';
import { normalizeItemGroup, getFirstFragmentPositions, getPlannedGroupHeadersByItemIndex, useMetaDefaultsCheck, cloneAsChild, resolveItemMeta, resolveItemClassName, renderFlowItem, breakAttributes, unplaceableFitStyle, shadowSplit, splitFragment, splitPosition, type FlowItemRendering } from './flow-render';
import type { FlowProps, DefaultFlowItemType, StaticFlowFragmentContext } from './flow-types';
export function Flow<TItem, TType extends string = DefaultFlowItemType<TItem>>({
  id,
  items,
  getKey,
  renderItem,
  getItemMeta,
  metaDefaults,
  getItemType: resolveItemType,
  getItemGroup,
  renderGroupHeader,
  className = '',
  itemClassName,
  groupHeaderClassName,
  renderUnplaceableItem,
  asChild = false,
  as = 'div',
}: FlowProps<TItem, TType>) {
  const context = React.useContext(StaticFlowContext);
  // `growSheet` applies in the screen view only: print never plans a sheet that grows.
  const growSheets = useView() === 'screen';
  // The piece of an outer Flow's item this Flow renders in: its group headers are not that piece.
  const outerSplit = React.useContext(FlowTextSplitContext);
  const Root = as as React.ElementType;
  const chunks = context?.chunksByFlowId?.[id];
  const activeChunk = context?.mode === 'visible' && chunks
    ? chunks[context.pageIndex]
    : undefined;
  const pageIndex = context?.mode === 'visible' ? context.pageIndex : 0;
  const pageCount = context?.mode === 'visible' && chunks ? chunks.length : 1;
  const unplaceable = activeChunk?.unplaceable;
  // A custom renderer that returns nothing falls back to the default, as before.
  const customUnplaceable = unplaceable
    ? renderUnplaceableItem?.(unplaceable, { flowId: id, pageIndex, pageCount })
    : undefined;
  const renderOriginalUnplaceable = Boolean(unplaceable && customUnplaceable == null);
  // A continuation measurement copy only lays the region out: its height is all that is read.
  const plannedIndexes = context?.copy === 'continuation'
    ? []
    : context?.mode === 'visible' && chunks
      ? (activeChunk?.indexes ?? [])
      : context?.mode === 'visible' && context.pageIndex > 0
        ? []
        : items.map((_, index) => index);
  // Preview and export render the same document content. Diagnostics are separate.
  const rawVisibleIndexes = renderOriginalUnplaceable
    ? [...new Set([...plannedIndexes, unplaceable!.index])].sort((a, b) => a - b)
    : plannedIndexes;

  // Guard against stale chunk indexes when items shrink (e.g. rowCount decreased before remeasure)
  const visibleIndexes = rawVisibleIndexes.filter((idx) => (
    Number.isInteger(idx) && idx >= 0 && idx < items.length
  ));
  const itemGroups = items.map((item, index) => normalizeItemGroup(getItemGroup?.(item, index)));
  const groupKeys = itemGroups.map((group) => group?.key);
  const fragmentPositions = getFirstFragmentPositions(visibleIndexes);
  const plannedGroupHeaders = renderGroupHeader
    ? getPlannedGroupHeadersByItemIndex(activeChunk?.groupHeaders)
    : undefined;

  useMetaDefaultsCheck('Flow', id, items, metaDefaults, resolveItemType);
  const rendering: FlowItemRendering<TItem> = { flowId: id, asChild, renderItem, renderGroupHeader, groupHeaderClassName };

  return (
    <Root
      className={className}
      data-uhuu-flow="true"
      data-uhuu-flow-id={id}
      data-uhuu-flow-as-child={asChild ? 'true' : undefined}
      data-uhuu-flow-item-count={asChild && context?.mode !== 'visible' ? visibleIndexes.length : undefined}
    >
      {unplaceable && customUnplaceable != null && ((asChild && cloneAsChild(customUnplaceable, {
        'data-uhuu-flow-unplaceable': 'true',
        'data-uhuu-flow-unplaceable-key': unplaceable.key,
      }, { flowId: id, source: 'renderUnplaceableItem' })) || (
        <div
          // No box of its own: a template's fallback lays out exactly as when it was returned bare.
          style={{ display: 'contents' }}
          data-uhuu-flow-unplaceable="true"
          data-uhuu-flow-unplaceable-key={unplaceable.key}
        >
          {customUnplaceable}
        </div>
      ))}
      {visibleIndexes.map((itemIndex) => {
        const item = items[itemIndex];
        if (item === undefined) return null;

        const key = getKey(item, itemIndex);
        const group = itemGroups[itemIndex];
        const coreFragment = getFlowFragmentState({
          itemIndex,
          fragmentIndexes: visibleIndexes,
          fragmentIndex: fragmentPositions.get(itemIndex) ?? -1,
          groupKeys,
          pageIndex,
          pageCount,
          itemCount: items.length,
        });
        const split = activeChunk?.splits?.[itemIndex];
        const fragment: StaticFlowFragmentContext<TItem> = {
          ...coreFragment,
          flowId: id,
          itemKey: key,
          item,
          ...(split ? splitFragment(split, coreFragment) : {}),
        };
        const meta = resolveItemMeta(item, itemIndex, resolveItemType, metaDefaults, getItemMeta);
        const isOriginalUnplaceable = renderOriginalUnplaceable && itemIndex === unplaceable?.index;
        const { header, element } = renderFlowItem(rendering, {
          item,
          itemIndex,
          fragment,
          group,
          plannedGroupHeaders,
          className: resolveItemClassName(itemClassName, item, itemIndex),
          attributes: {
            'data-uhuu-flow-item': 'true',
            'data-uhuu-flow-key': String(key),
            'data-uhuu-flow-index': itemIndex,
            ...breakAttributes(meta, group),
            'data-uhuu-flow-unplaceable': isOriginalUnplaceable ? 'true' : undefined,
            'data-uhuu-flow-unplaceable-key': isOriginalUnplaceable ? unplaceable!.key : undefined,
            'data-uhuu-flow-orphans': serializeLineCount(meta.orphans),
            'data-uhuu-flow-widows': serializeLineCount(meta.widows),
            'data-uhuu-flow-split': split ? splitPosition(split) : undefined,
            'data-uhuu-flow-grow-sheet': growSheets && meta.growSheet ? 'true' : undefined,
            'data-uhuu-flow-header-grow-sheet': growSheets && group?.growSheet ? 'true' : undefined,
          },
          forcedStyle: isOriginalUnplaceable ? unplaceableFitStyle(unplaceable!) : undefined,
        });

        // The piece this item renders, for its Static.FlowText (none: the whole item). Always
        // provided, so a re-plan that splits an item does not remount it, and a Flow nested in a
        // split piece does not hand that piece to its own items.
        return (
          <React.Fragment key={key}>
            {outerSplit ? shadowSplit(header) : header}
            <FlowTextSplitContext.Provider value={split ?? null}>{element}</FlowTextSplitContext.Provider>
          </React.Fragment>
        );
      })}
    </Root>
  );
}
