export const DEFAULT_MEDIA_KINDS = [
    { id: "photos", label: "Photos" },
    { id: "graphics", label: "Graphics" },
    { id: "icons", label: "Icons" },
    { id: "backgrounds", label: "Backgrounds" },
    { id: "templates", label: "Templates" },
];
const EXTENSION_KEY = /^[A-Za-z][A-Za-z0-9_-]{0,40}$/;
export function isExtensionKey(value) {
    return EXTENSION_KEY.test(value);
}
/**
 * The only supported authoring-document schema. Retired schemas are rejected without upgrading
 * stored data. Template-owned values are authored only in namespaced extensions.
 */
export const BRAND_KIT_SCHEMA_VERSION = 5;
/** Maps BrandMediaDefaultKind to its corresponding BrandMediaAssignments key. */
export const MEDIA_ASSIGNMENT_KEYS = {
    photos: "activePhotoCollectionId",
    graphics: "activeGraphicCollectionId",
    icons: "activeIconCollectionId",
    backgrounds: "activeBackgroundCollectionId",
    templates: "activeTemplateCollectionId",
};
/** Converts a BrandMediaKind to its singular string type label. */
export function mediaTypeFromKind(kind) {
    const singular = {
        photos: "photo",
        graphics: "graphic",
        icons: "icon",
        backgrounds: "background",
        templates: "template",
    };
    return singular[kind] ?? kind.replace(/s$/, "");
}
/** Public collection assignment key for built-in and team-defined media kinds. */
export function mediaAssignmentKeyFromKind(kind) {
    return `media.${kind}`;
}
