import { useCallback, useContext, useEffect, useId, useMemo, useRef, useState, type CSSProperties } from 'react';
import { createPortal } from 'react-dom';
import { Pencil, SlidersHorizontal } from 'lucide-react';
import { Button } from '../../ui/button';
import { cn } from '../../ui/cn';
import { useShellTranslation } from '../../i18n/locale-context';
import type { LocalizedText } from '../../i18n/i18n-core.js';
import { isRendererMode, useInteractive } from '../interactive-mode-context';
import { createPortalContainer, usePortalRoot } from '../portal-root';
import { getToolbarSlot, useToolbarSlot } from '../toolbar-slot';
import { DEFAULT_TOOLBAR_POSITION, TOOLBAR_CORNER_CLASS, isToolbarPosition, type ToolbarPosition } from '../toolbar-position';
import { TemplateDataContext } from './template-data-provider';
import { OptionControl, OptionControlList, type OptionChoiceValue } from './option-controls';
import { findOptionChoice, isOptionOn, optionField, optionType, sameOptionValue } from './option-core.js';
import {
  DOCUMENT_OPTION_PATCH_TIMEOUT,
  coerceDocumentOptionValue,
  documentOptionEditDialog,
  documentOptionKey,
  documentOptionPatchMessage,
  documentOptionWriteMode,
  readDocumentOption,
  type DocumentOptionDefinition,
  type DocumentOptionsHost,
} from './document-options-core.js';

export type { DocumentOptionDefinition } from './document-options-core.js';

export interface DocumentOptionsProps {
  /**
   * The document payload the template renders. Without it the control reads the surrounding
   * TemplateDataProvider's payload.
   */
  payload?: Record<string, unknown> | null;
  /** Defined as payload page options are: `id` names the top-level key (`field` overrides it). */
  options: DocumentOptionDefinition[];
  /** Heading of the control; default: the shell's "Document options", in the interface language. */
  title?: LocalizedText;
  /** Called for local choices, when there is no uhuu document editor on the page. */
  onChange?: (key: string, value: unknown) => void;
  /** The corner of the control's own floating bar, drawn when no PageEditor toolbar is on screen. */
  toolbarPosition?: ToolbarPosition;
  /** The control's own floating bar, or its entry inside PageEditor's toolbar. */
  className?: string;
  style?: CSSProperties;
}

type PendingChoice = { value: unknown; previousValue: unknown; token: number };

// Whether this page's editor renders a `patchPayload` back, learnt from the first patch.
let patchSupport: 'unknown' | 'supported' | 'unsupported' = 'unknown';
let warnedNoHost = false;
let warnedNoKey = false;

const LABEL = 'uhuu:text-xs uhuu:font-medium uhuu:text-gray-500';

function pageHost(): DocumentOptionsHost | undefined {
  return typeof window === 'undefined' ? undefined : (window as any).$uhuu;
}

/**
 * A portal container of the control's own, for a page without InteractiveModeProvider (whose
 * container the shell's scoped styles reach). Created after mount, never on the server.
 */
function useOwnPortalContainer(enabled: boolean): HTMLElement | null {
  const [container, setContainer] = useState<HTMLElement | null>(null);
  useEffect(() => {
    if (!enabled || typeof document === 'undefined') return;
    // A PageEditor toolbar registered in this commit: the control joins it instead.
    if (getToolbarSlot()) return;
    const element = createPortalContainer();
    document.body.appendChild(element);
    setContainer(element);
    return () => {
      element.remove();
      setContainer(null);
    };
  }, [enabled]);
  return enabled ? container : null;
}

/**
 * Document-level options a template draws in the editor shell: controls for top-level payload
 * keys (`payload.language`) that the platform's template theme options used to show in the editor
 * header. Defined, valued and drawn as page options are; only where they live differs.
 *
 * A choice is a person's edit: the uhuu document editor writes it (`patchPayload`), marks the
 * document modified and renders it back. An editor that does not render the patch back opens its
 * own field (`$uhuu.editDialog`) instead, for this and later choices.
 *
 * Joins PageEditor's floating toolbar when one is on screen, else draws its own small floating bar
 * (bottom right by default). Never drawn outside edit mode, in the PDF renderer or in print.
 */
export function DocumentOptions({ payload: payloadProp, options, title, onChange, toolbarPosition, className, style }: DocumentOptionsProps) {
  const { interactive } = useInteractive();
  const { t, localize } = useShellTranslation();
  const templateData = useContext(TemplateDataContext);
  const payload = payloadProp ?? templateData?.payload ?? null;
  const definitions = useMemo(() => {
    const list = Array.isArray(options) ? options : [];
    const keyed = list.filter((definition) => typeof optionField(definition) === 'string');
    if (keyed.length !== list.length && !warnedNoKey) {
      warnedNoKey = true;
      console.warn('[uhuu-components] DocumentOptions: an option without `id` (or `field`) is left out.');
    }
    return keyed;
  }, [options]);
  const byKey = useMemo(() => new Map(definitions.map((definition) => [documentOptionKey(definition) as string, definition])), [definitions]);

  const visible = interactive && !isRendererMode() && definitions.length > 0;
  const toolbarSlot = useToolbarSlot();
  const portalRoot = usePortalRoot();
  // Outside InteractiveModeProvider there is no shell portal to draw the floating bar into.
  const ownContainer = useOwnPortalContainer(visible && !toolbarSlot && !portalRoot.inProvider);
  const container = toolbarSlot ?? portalRoot.portalContainer ?? ownContainer;

  const id = useId();
  const panelId = `${id}-panel`;
  const headingId = `${id}-heading`;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [placement, setPlacement] = useState<{ side: 'top' | 'bottom'; align: 'start' | 'end'; maxHeight?: number }>({ side: 'top', align: 'end' });
  // Re-renders the panel when the first patch shows the editor's support (module state).
  const [, setPatchSupportSeen] = useState(patchSupport);

  // Choices not yet in the payload: shown in place of the stored value until that value changes
  // (the editor's render-back, or another editor control), then the payload is authoritative again.
  const [pending, setPendingState] = useState<Record<string, PendingChoice>>({});
  const pendingRef = useRef(pending);
  const setPending = useCallback((next: Record<string, PendingChoice>) => {
    pendingRef.current = next;
    setPendingState(next);
  }, []);
  const tokenRef = useRef(0);
  const timers = useRef(new Map<string, ReturnType<typeof setTimeout>>());
  const clearTimer = useCallback((key: string) => {
    const timer = timers.current.get(key);
    if (timer !== undefined) clearTimeout(timer);
    timers.current.delete(key);
  }, []);
  useEffect(() => {
    const pendingTimers = timers.current;
    return () => {
      pendingTimers.forEach((timer) => clearTimeout(timer));
      pendingTimers.clear();
    };
  }, []);

  useEffect(() => {
    const previous = pendingRef.current;
    const remaining: Record<string, PendingChoice> = {};
    let changed = false;
    for (const [key, entry] of Object.entries(previous)) {
      const definition = byKey.get(key);
      const stored = definition ? readDocumentOption(payload, definition) : undefined;
      if (definition && Object.is(stored, entry.previousValue)) {
        remaining[key] = entry;
        continue;
      }
      changed = true;
      clearTimer(key);
      if (definition && patchSupport === 'unknown' && sameOptionValue(stored, entry.value)) {
        patchSupport = 'supported';
        setPatchSupportSeen(patchSupport);
      }
    }
    if (changed) setPending(remaining);
  }, [payload, byKey, setPending, clearTimer]);

  const valueOf = (definition: DocumentOptionDefinition) => {
    const stored = readDocumentOption(payload, definition);
    const entry = pending[documentOptionKey(definition) as string];
    return entry && Object.is(stored, entry.previousValue) ? entry.value : stored;
  };

  const closePanel = useCallback((restoreFocus: boolean) => {
    setOpen(false);
    if (restoreFocus) triggerRef.current?.focus();
  }, []);

  const openPanel = () => {
    const rect = triggerRef.current?.getBoundingClientRect();
    if (rect && typeof window !== 'undefined') {
      // Open towards the larger part of the viewport, lined up with the toolbar's outer edge.
      const side = rect.top + rect.height / 2 > window.innerHeight / 2 ? 'top' : 'bottom';
      const align = rect.left + rect.width / 2 > window.innerWidth / 2 ? 'end' : 'start';
      const room = side === 'top' ? rect.top : window.innerHeight - rect.bottom;
      setPlacement({ side, align, maxHeight: Math.max(160, Math.floor(room - 24)) });
    }
    setOpen(true);
  };

  // Hidden (export mode, DEV print modes) closes the panel: it reopens from the trigger.
  useEffect(() => {
    if (!visible) setOpen(false);
  }, [visible]);

  useEffect(() => {
    if (!open) return;
    panelRef.current?.querySelector<HTMLElement>('select, button, [role="slider"]')?.focus();
    const closeOnOutsidePointer = (event: PointerEvent) => {
      if (!wrapperRef.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', closeOnOutsidePointer, true);
    return () => document.removeEventListener('pointerdown', closeOnOutsidePointer, true);
  }, [open]);

  // The editor's field shows the stored value (`value` only while there is none).
  const openEditorDialog = (definition: DocumentOptionDefinition) => {
    const uhuu = pageHost();
    if (typeof uhuu?.editDialog !== 'function') return;
    uhuu.editDialog(documentOptionEditDialog(definition, readDocumentOption(payload, definition), localize));
    setOpen(false);
  };

  const keepLocally = (definition: DocumentOptionDefinition, value: unknown) => {
    const key = documentOptionKey(definition) as string;
    if (!warnedNoHost) {
      warnedNoHost = true;
      console.warn('[uhuu-components] DocumentOptions: no uhuu document editor on this page; a change only calls onChange.');
    }
    setPending({ ...pendingRef.current, [key]: { value, previousValue: readDocumentOption(payload, definition), token: ++tokenRef.current } });
    onChange?.(key, value);
  };

  const write = (definition: DocumentOptionDefinition, choice: OptionChoiceValue) => {
    const uhuu = pageHost();
    const mode = documentOptionWriteMode(uhuu);
    const key = documentOptionKey(definition) as string;
    const value = coerceDocumentOptionValue(definition, choice);

    if (mode === 'patch' && patchSupport !== 'unsupported') {
      const token = ++tokenRef.current;
      setPending({ ...pendingRef.current, [key]: { value, previousValue: readDocumentOption(payload, definition), token } });
      uhuu!.editor!.post!(documentOptionPatchMessage(definition, value));
      if (patchSupport === 'supported') return;
      clearTimer(key);
      timers.current.set(key, setTimeout(() => {
        timers.current.delete(key);
        const entry = pendingRef.current[key];
        if (!entry || entry.token !== token || patchSupport !== 'unknown') return;
        // Nothing came back: an editor without patchPayload. Its field dialog writes the key.
        patchSupport = 'unsupported';
        setPatchSupportSeen(patchSupport);
        const { [key]: _dropped, ...rest } = pendingRef.current;
        if (typeof pageHost()?.editDialog === 'function') {
          setPending(rest);
          openEditorDialog(definition);
        } else {
          keepLocally(definition, value);
        }
      }, DOCUMENT_OPTION_PATCH_TIMEOUT));
      return;
    }
    if (typeof uhuu?.editDialog === 'function') {
      openEditorDialog(definition);
      return;
    }
    keepLocally(definition, value);
  };

  if (!visible || !container || typeof document === 'undefined') return null;

  const resolvedTitle = localize(title) ?? t('documentOptions.title');
  // Read on every render: the SDK is a script the page loads before the template.
  const host = pageHost();
  const mode = documentOptionWriteMode(host);
  const throughDialog = typeof host?.editDialog === 'function'
    && (mode === 'dialog' || (mode === 'patch' && patchSupport === 'unsupported'));

  // An editor without patchPayload: each option opens the editor's field, drawn like the select.
  const renderDialogRow = (definition: DocumentOptionDefinition) => {
    const key = documentOptionKey(definition) as string;
    const label = localize(definition.label) ?? key;
    const value = valueOf(definition);
    const type = optionType(definition);
    const choice = type === 'toggle' ? undefined : findOptionChoice(definition, value);
    const empty = value === undefined || value === null || value === '';
    const valueLabel = type === 'toggle'
      ? t(isOptionOn(value) ? 'documentOptions.on' : 'documentOptions.off')
      : choice ? (localize(choice.label) ?? String(choice.value)) : empty ? t('options.notSet') : String(value);
    const description = localize(definition.description);
    const labelId = `${id}-${key}-label`;
    const descriptionId = `${id}-${key}-description`;
    return (
      <div key={key} className="uhuu:flex uhuu:flex-col uhuu:gap-1.5">
        <span id={labelId} className={cn(LABEL, 'uhuu:block')}>{label}</span>
        <button
          type="button"
          aria-haspopup="dialog"
          aria-labelledby={`${labelId} ${id}-${key}-value`}
          aria-describedby={description ? descriptionId : undefined}
          title={t('documentOptions.change', { name: label })}
          onClick={() => openEditorDialog(definition)}
          className="uhuu:relative uhuu:flex uhuu:h-8 uhuu:w-full uhuu:items-center uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:py-1 uhuu:pr-8 uhuu:pl-2.5 uhuu:text-left uhuu:text-sm uhuu:text-gray-900 uhuu:transition-colors uhuu:hover:border-gray-300 uhuu:focus-visible:border-gray-400 uhuu:focus-visible:outline-none uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-200"
        >
          <span id={`${id}-${key}-value`} className="uhuu:truncate">{valueLabel}</span>
          <Pencil aria-hidden="true" className="uhuu:pointer-events-none uhuu:absolute uhuu:top-1/2 uhuu:right-2.5 uhuu:h-3.5 uhuu:w-3.5 uhuu:-translate-y-1/2 uhuu:text-gray-500" />
        </button>
        {description && <p id={descriptionId} className="uhuu:text-xs uhuu:leading-snug uhuu:text-gray-500">{description}</p>}
      </div>
    );
  };

  const entry = (
    <div
      ref={wrapperRef}
      className={cn('uhuu-screen-only uhuu:relative uhuu:flex uhuu:items-center', toolbarSlot && className)}
      style={toolbarSlot ? style : undefined}
      onKeyDown={(event) => {
        if (event.key !== 'Escape' || !open) return;
        event.preventDefault();
        event.stopPropagation();
        closePanel(true);
      }}
      onBlur={(event) => {
        const next = event.relatedTarget as Node | null;
        if (open && next && !wrapperRef.current?.contains(next)) setOpen(false);
      }}
    >
      <Button
        ref={triggerRef}
        type="button"
        variant="ghost"
        size="sm"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => (open ? closePanel(false) : openPanel())}
        className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:bg-gray-100/80 uhuu:h-7 uhuu:px-2.5 uhuu:gap-1.5"
      >
        <SlidersHorizontal aria-hidden="true" className="uhuu:w-3.5 uhuu:h-3.5" />
        {resolvedTitle}
      </Button>
      {open && (
        <div
          ref={panelRef}
          id={panelId}
          role="dialog"
          aria-labelledby={headingId}
          className={cn(
            'uhuu:absolute uhuu:z-50 uhuu:w-72 uhuu:max-w-[calc(100vw-2rem)] uhuu:overflow-y-auto uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:p-3 uhuu:text-gray-900 uhuu:shadow-md',
            placement.side === 'top' ? 'uhuu:bottom-full uhuu:mb-3' : 'uhuu:top-full uhuu:mt-3',
            placement.align === 'end' ? 'uhuu:right-0' : 'uhuu:left-0',
          )}
          style={{ maxHeight: placement.maxHeight }}
        >
          <h2 id={headingId} className="uhuu:mb-3 uhuu:text-sm uhuu:font-medium uhuu:text-gray-900">{resolvedTitle}</h2>
          <OptionControlList>
            {definitions.map((definition) => throughDialog
              ? renderDialogRow(definition)
              : (
                <OptionControl
                  key={documentOptionKey(definition) as string}
                  definition={definition}
                  value={valueOf(definition)}
                  onChange={(value) => write(definition, value)}
                />
              ))}
          </OptionControlList>
        </div>
      )}
    </div>
  );

  if (toolbarSlot) return createPortal(entry, toolbarSlot);

  const corner = isToolbarPosition(toolbarPosition) ? toolbarPosition : DEFAULT_TOOLBAR_POSITION;
  return createPortal(
    <div
      data-uhuu-editor
      data-uhuu-toolbar-position={corner}
      className={cn(
        'uhuu-screen-only uhuu:fixed uhuu:z-50 uhuu:flex uhuu:items-center uhuu:p-1.5 uhuu:bg-(--uhuu-shell-surface)/90 uhuu:backdrop-blur-md uhuu:border uhuu:border-gray-200/60 uhuu:rounded-lg uhuu:shadow-sm',
        TOOLBAR_CORNER_CLASS[corner],
        className,
      )}
      style={style}
    >
      {entry}
    </div>,
    container,
  );
}
