/** The wire version this producer writes. Readers accept every supported-major document. */
export const PUBLIC_BRANDKIT_JSON_VERSION = "3.0";
export const PUBLIC_BRANDKIT_JSON_MAJOR = 3;
export function isPublicBrandKitJsonVersion(value) {
    return typeof value === "string" && /^3(?:\.\d+){0,2}$/.test(value);
}
