/**
 * Numbers, money and dates in the document's language, with Swiss print conventions
 * (`CHF 3'600'000.–`) built in, so templates stop copying their own formatters.
 *
 * The locale is the caller's (`payload.locale`), else the brand's default from
 * `extensions.locale.strings.default`, else the runtime's. The currency is the caller's, else the
 * brand's `extensions.locale.strings.currency`, else `CHF`.
 *
 * Pure and DOM-free.
 */
import { isPlainObject, textOf } from '../utility/json.js';

/** The brand's default locale and currency (`extensions.locale.strings`). */
export function brandKitLocale(brandKit) {
  const strings = isPlainObject(brandKit) && isPlainObject(brandKit.extensions?.locale?.strings) ? brandKit.extensions.locale.strings : {};
  const locale = textOf(strings.default);
  const currency = textOf(strings.currency);
  return { ...(locale ? { locale } : {}), ...(currency ? { currency } : {}) };
}

/** `options` without the keys this module reads, for `Intl`. */
function intlOptions(options) {
  const intl = { ...options };
  for (const key of ['locale', 'brandKit', 'apostrophe', 'currency', 'wholeDash']) delete intl[key];
  return intl;
}

const isSwiss = (locale) => /-CH$/i.test(locale ?? '') || /^(de|fr|it|rm)-li$/i.test(locale ?? '');

function localeOf(options) {
  return textOf(options.locale) ?? brandKitLocale(options.brandKit).locale;
}

/** Swiss print style groups thousands with a straight apostrophe; `typographic` keeps `’`. */
function swissGroups(text, apostrophe) {
  return apostrophe === 'typographic' ? text.replace(/'/g, '’') : text.replace(/[’’]/g, "'");
}

/**
 * A number. Swiss locales group with `'` (`apostrophe: 'typographic'` for `’`).
 *
 * @param {number} value
 * @param {{ locale?: string, brandKit?: object, apostrophe?: 'straight'|'typographic' } & Intl.NumberFormatOptions} [options]
 */
export function formatNumber(value, options = {}) {
  const number = Number(value);
  if (!Number.isFinite(number)) return '';
  const locale = localeOf(options);
  const text = new Intl.NumberFormat(locale, intlOptions(options)).format(number);
  return isSwiss(locale) ? swissGroups(text, options.apostrophe) : text;
}

/**
 * An amount of money. Swiss locales print `CHF 3'600'000.–` for whole amounts and
 * `CHF 1'250.50` otherwise (`wholeDash: false` prints `.00`); other locales use `Intl`'s currency
 * format.
 *
 * @param {number} value
 * @param {{ locale?: string, currency?: string, brandKit?: object, wholeDash?: boolean, apostrophe?: 'straight'|'typographic' }} [options]
 */
export function formatMoney(value, options = {}) {
  const number = Number(value);
  if (!Number.isFinite(number)) return '';
  const locale = localeOf(options);
  const currency = textOf(options.currency) ?? brandKitLocale(options.brandKit).currency ?? 'CHF';
  if (!isSwiss(locale)) {
    return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(number);
  }
  const whole = Number.isInteger(Math.round(number * 100) / 100) && Math.round(number * 100) % 100 === 0;
  const digits = whole && options.wholeDash !== false ? 0 : 2;
  const amount = formatNumber(Math.abs(number), { locale, apostrophe: options.apostrophe, minimumFractionDigits: digits, maximumFractionDigits: digits });
  const sign = number < 0 ? '-' : '';
  return `${currency} ${sign}${amount}${digits === 0 ? '.–' : ''}`;
}

/**
 * A date (`Date`, ISO string or timestamp) in the document's language; `dateStyle` defaults to
 * `long` (`16. Oktober 2026`). `''` for an invalid date.
 *
 * @param {Date|string|number} value
 * @param {{ locale?: string, brandKit?: object } & Intl.DateTimeFormatOptions} [options]
 */
export function formatDate(value, options = {}) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const intl = intlOptions(options);
  const hasFields = ['dateStyle', 'year', 'month', 'day', 'weekday'].some((key) => key in intl);
  return new Intl.DateTimeFormat(localeOf(options), hasFields ? intl : { dateStyle: 'long', ...intl }).format(date);
}
