import * as React from 'react';
import { Lock } from 'lucide-react';
import { ReorderItem } from './page-group-utils';
import type { PageComponent, PageEditorPage, PageGroup, StandalonePage } from './page-group-utils';
import { buildPageDataBinding } from './data-binding';
import { warnOnce } from '../../utility/warn-once.js';
import { getPagePayload } from './template-data-provider';
import { resolveIntegrationForPage } from './integration-utils';
import PageSizeUtils from '../../utility/PageSizeUtils';
import type { ShellI18n } from '../../i18n/locale-context';
import { readDocumentTypography } from './document-typography';
import { useIsoLayoutEffect } from '../../utility/use-iso-layout-effect';

type TypographyLease = { style: React.CSSProperties; release: () => void };

/**
 * A page that throws while drawn as a thumbnail shows the card's fallback instead of taking the
 * editor down with it, and says which page failed.
 */
class ThumbnailBoundary extends React.Component<{ pageId?: string; fallback: React.ReactNode; children: React.ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  componentDidCatch(error: unknown) {
    warnOnce(
      `thumbnail:${this.props.pageId ?? ''}:${String(error)}`,
      `[uhuu-components] Page "${this.props.pageId ?? ''}" failed to render as a reorder thumbnail; its card shows no preview.`,
      error
    );
  }
  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

/** The page as the editor hands it to a page component: its first sheet of one. */
function thumbnailPage(page: StandalonePage | undefined): PageEditorPage | undefined {
  return page ? { ...page, virtualPageIndex: 0, virtualPageCount: 1 } : undefined;
}

/** Closed dialogs construct cards without mounting them. Read the document only after mounting. */
function ThumbnailPage({ children, style, acquireTypography }: {
  children: React.ReactNode;
  style: React.CSSProperties;
  acquireTypography: () => TypographyLease;
}) {
  const [typography, setTypography] = React.useState<React.CSSProperties>();
  useIsoLayoutEffect(() => {
    const lease = acquireTypography();
    setTypography(lease.style);
    return lease.release;
  }, [acquireTypography]);
  return <div className="uhuu:shrink-0!" style={{ ...typography, ...style }}>{children}</div>;
}

interface DefaultRenderThumbnailOptions {
  // PageComponent registry: map of pageId to React component
  pageComponents: { [pageId: string]: PageComponent };
  
  // Payload to pass to PageComponents
  payload?: any;
  
  // Page setup (same as Pagination setup prop) - supports format/orientation or explicit width/height in mm
  setup?: { width?: number; height?: number; [key: string]: any };
  
  // Optional: Custom thumbnail dimensions (height auto-derives from page aspect if omitted)
  thumbnailWidth?: number;
  thumbnailHeight?: number;

  // The shell's words and language (from useShellTranslation in the calling component)
  i18n: ShellI18n;
}

/**
 * Creates a default renderThumbnail function that renders actual PageComponents
 * instead of reference images. This ensures thumbnails accurately represent
 * the rendered page content.
 * 
 * @internal - This is an internal utility, not part of the public API
 */
export function createDefaultRenderThumbnail(
  options: DefaultRenderThumbnailOptions
): (item: ReorderItem, index: number, isDragging?: boolean) => React.ReactNode {
  const { 
    pageComponents, 
    payload, 
    setup = { width: 210, height: 297 }, // Default A4 size in mm
    thumbnailWidth = 200, 
    thumbnailHeight, 
    i18n,
  } = options;
  const { t, localize } = i18n;

  // Resolve actual dimensions using PageSizeUtils so format/orientation are respected
  // (e.g. { format: 'A4', orientation: 'landscape' } correctly yields 297×210)
  const resolvedDimensions = PageSizeUtils.resolveDimensions(setup);
  const pageWidthMm = resolvedDimensions.width;
  const pageHeightMm = resolvedDimensions.height;
  const pageAspectRatio = pageWidthMm / pageHeightMm;

  // Derive thumbnail height from page aspect ratio if not provided
  const finalThumbnailWidth = thumbnailWidth;
  const finalThumbnailHeight = thumbnailHeight ?? Math.round(finalThumbnailWidth / pageAspectRatio);

  // The page in CSS px, for scaling it into the thumbnail.
  const pageWidthPx = PageSizeUtils.mmToPx(pageWidthMm);
  const pageHeightPx = PageSizeUtils.mmToPx(pageHeightMm);

  // Share one typography read across the mounted dialog's cards. The final unmount releases the
  // snapshot, so reopening after template CSS/font changes takes the document's current type.
  let documentTypography: React.CSSProperties | undefined;
  let mountedCards = 0;
  const acquireTypography = (): TypographyLease => {
    documentTypography ??= readDocumentTypography() ?? {};
    mountedCards += 1;
    return { style: documentTypography, release: () => {
      mountedCards -= 1;
      if (!mountedCards) documentTypography = undefined;
    } };
  };
  const pageStyle: React.CSSProperties = { width: `${pageWidthPx}px`, height: `${pageHeightPx}px`, backgroundColor: 'white', pointerEvents: 'none' };

  
  // The card is paper (data-uhuu-paper): the page in it looks as authored, its template's base
  // styles included. What the shell draws over it (badges, lock, caption, drag hint, the fallback)
  // is chrome on paper (data-uhuu-chrome), which the shell's reset still styles.
  // A render callback for the reorder grid, not a component: it needs no display name.
  // eslint-disable-next-line react/display-name
  return (item: ReorderItem, index: number, isDragging?: boolean) => {
    const strictPosition = (item as any).strictPosition;
    const isLocked = strictPosition === 'start' || strictPosition === 'end';
    
    if (item.kind === 'group') {
      // Group thumbnail: show first page with group indicator
      const firstPageId = item.firstPageId as string | undefined;
      const firstPageComponentKey = item.firstPageComponentKey ?? firstPageId;
      const firstPagePayload = getPagePayload(payload, { id: firstPageId, componentKey: firstPageComponentKey });
      // Use component from item if available, otherwise fall back to pageComponents registry
      const FirstPageComponent = item.firstPageComponent || (firstPageComponentKey ? pageComponents[firstPageComponentKey] : null);
      
      // Resolve integration data for group (group pages use the group's integration)
      // For groups, instanceId is the group ID, so we can directly access it
      const integration = payload?.integrations?.[item.id];      
      
      return (
        <div 
          data-uhuu-paper
          className={`uhuu:relative uhuu:bg-white uhuu:border uhuu:transition-all ${
            isDragging 
              ? 'uhuu:border-blue-400 uhuu:shadow-2xl uhuu:scale-105' 
              : isLocked
              ? 'uhuu:border-(--uhuu-thumbnail-border-strong) uhuu:bg-gray-50'
              : 'uhuu:border-(--uhuu-thumbnail-border) uhuu:hover:border-(--uhuu-thumbnail-border-strong) uhuu:hover:shadow-lg'
          }`}
          style={{ width: `${finalThumbnailWidth}px`, height: `${finalThumbnailHeight}px` }}
          title={item.id}
        >
          {/* Render actual PageComponent */}
          {FirstPageComponent ? (
            <div 
              className="uhuu:w-full uhuu:h-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-gray-50 uhuu:overflow-hidden uhuu:relative uhuu:pointer-events-none"
            >
              <div 
                style={{
                  transform: `scale(${Math.min(finalThumbnailWidth / pageWidthPx, finalThumbnailHeight / pageHeightPx)})`,
                  transformOrigin: 'center',
                }}
              >
                <ThumbnailBoundary pageId={firstPageId} fallback={null}>
                  <ThumbnailPage style={pageStyle} acquireTypography={acquireTypography}>
                    <FirstPageComponent
                      payload={payload}
                      pageId={firstPageId}
                      templateId={firstPageComponentKey}
                      pagePayload={firstPagePayload}
                      componentKey={firstPageComponentKey}
                      integration={integration}
                      page={thumbnailPage(item.page)}
                      parentGroup={(item.group ?? item) as PageGroup}
                      pageNum={index + 1}
                      dataBinding={item.page ? buildPageDataBinding({ payload, page: item.page, parentGroup: item.group, pagePayload: firstPagePayload }) : undefined}
                    />
                  </ThumbnailPage>
                </ThumbnailBoundary>
              </div>
            </div>
          ) : (
            <div data-uhuu-chrome className="uhuu:w-full uhuu:h-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-gray-50 uhuu:pointer-events-none">
              <div className="uhuu:text-center uhuu:p-4">
                <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{t('thumbnail.groupFallbackName', { id: item.id })}</div>
                <div className="uhuu:text-xs uhuu:text-gray-500 uhuu:mt-1">{firstPageId || t('thumbnail.noPreview')}</div>
              </div>
            </div>
          )}
          
          {/* Group indicator badge */}
          <div data-uhuu-chrome className="uhuu:absolute uhuu:top-2 uhuu:right-2 uhuu:px-2 uhuu:py-1 uhuu:bg-blue-600/80 uhuu:backdrop-blur-sm uhuu:text-white uhuu:text-xs uhuu:font-medium uhuu:rounded uhuu:shadow-lg uhuu:pointer-events-none">
            {t('thumbnail.groupBadge', { count: item.pageCount })}
          </div>
          
          {/* Lock indicator for strict position */}
          {isLocked && (
            <div data-uhuu-chrome className="uhuu:absolute uhuu:top-2 uhuu:left-2 uhuu:px-2 uhuu:py-1 uhuu:bg-gray-600/80 uhuu:backdrop-blur-sm uhuu:text-white uhuu:text-xs uhuu:font-medium uhuu:rounded uhuu:shadow-lg uhuu:pointer-events-none uhuu:flex uhuu:items-center uhuu:gap-1">
              <Lock className="uhuu:size-3" />
              <span>{strictPosition === 'start' ? t('thumbnail.start') : t('thumbnail.end')}</span>
            </div>
          )}
          
          {/* Group info overlay */}
          <div data-uhuu-chrome className="uhuu:absolute uhuu:bottom-0 uhuu:left-0 uhuu:right-0 uhuu:bg-(--uhuu-thumbnail-caption) uhuu:backdrop-blur-sm uhuu:p-3 uhuu:pointer-events-none">
            <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-2 uhuu:text-white">
              <div className="uhuu:flex-1 uhuu:min-w-0">
                <div className="uhuu:text-sm uhuu:font-medium uhuu:truncate">
                  {localize(item.label) || item.id}
                </div>
              </div>
            </div>
          </div>
          
          {/* Drag indicator */}
          {isDragging && (
            <div data-uhuu-chrome className="uhuu:absolute uhuu:inset-0 uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-blue-500/10 uhuu:pointer-events-none">
              <div className="uhuu:text-blue-600 uhuu:font-medium uhuu:text-sm uhuu:bg-white/90 uhuu:px-3 uhuu:py-1 uhuu:rounded-full uhuu:shadow-lg">
                {t('thumbnail.draggingGroup')}
              </div>
            </div>
          )}
        </div>
      );
    } else {
      // Standalone page thumbnail
      const pageId = item.pageId as string | undefined;
      const pageComponentKey = item.pageComponentKey ?? pageId;
      const pagePayload = getPagePayload(payload, { id: pageId, componentKey: pageComponentKey });
      // Use component from item if available, otherwise fall back to pageComponents registry
      const PageComponent = item.pageComponent || (pageComponentKey ? pageComponents[pageComponentKey] : null);
      
      // Resolve integration data for standalone page
      const integration = pageId ? resolveIntegrationForPage(payload, { id: pageId }) : undefined;
      return (
        <div 
          data-uhuu-paper
          className={`uhuu:relative uhuu:bg-white uhuu:border uhuu:transition-all ${
            isDragging 
              ? 'uhuu:border-blue-400 uhuu:shadow-2xl uhuu:scale-105' 
              : isLocked
              ? 'uhuu:border-(--uhuu-thumbnail-border-strong) uhuu:bg-gray-50'
              : 'uhuu:border-(--uhuu-thumbnail-border) uhuu:hover:border-(--uhuu-thumbnail-border-strong) uhuu:hover:shadow-lg'
          }`}
          style={{ width: `${finalThumbnailWidth}px`, height: `${finalThumbnailHeight}px` }}
          title={item.pageId}
        >
          {/* Render actual PageComponent */}
          {PageComponent ? (
            <div 
              className="uhuu:w-full uhuu:h-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-gray-50 uhuu:overflow-hidden uhuu:relative uhuu:pointer-events-none"
            >
              <div 
                className="uhuu:flex uhuu:items-center uhuu:justify-center uhuu:pointer-events-none"
                style={{
                  transform: `scale(${Math.min(finalThumbnailWidth / pageWidthPx, finalThumbnailHeight / pageHeightPx)})`,
                  transformOrigin: 'center',
                }}
              >
                <ThumbnailBoundary pageId={pageId} fallback={null}>
                  <ThumbnailPage style={pageStyle} acquireTypography={acquireTypography}>
                    <PageComponent
                      payload={payload}
                      pageId={pageId}
                      templateId={pageComponentKey}
                      pagePayload={pagePayload}
                      componentKey={pageComponentKey}
                      integration={integration}
                      page={thumbnailPage(item.page)}
                      pageNum={index + 1}
                      dataBinding={item.page ? buildPageDataBinding({ payload, page: item.page, pagePayload }) : undefined}
                    />
                  </ThumbnailPage>
                </ThumbnailBoundary>
              </div>
            </div>
          ) : (
            <div data-uhuu-chrome className="uhuu:w-full uhuu:h-full uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-gray-50 uhuu:pointer-events-none">
              <div className="uhuu:text-center uhuu:p-4">
                <div className="uhuu:text-sm uhuu:font-medium uhuu:text-gray-700">{t('page.fallbackName', { number: item.pageNum })}</div>
                <div className="uhuu:text-xs uhuu:text-gray-500 uhuu:mt-1">{pageId || t('thumbnail.noPreview')}</div>
              </div>
            </div>
          )}
          
          {/* Lock indicator for strict position */}
          {isLocked && (
            <div data-uhuu-chrome className="uhuu:absolute uhuu:top-2 uhuu:left-2 uhuu:px-2 uhuu:py-1 uhuu:bg-gray-600/80 uhuu:backdrop-blur-sm uhuu:text-white uhuu:text-xs uhuu:font-medium uhuu:rounded uhuu:shadow-lg uhuu:pointer-events-none uhuu:flex uhuu:items-center uhuu:gap-1">
              <Lock className="uhuu:size-3" />
              <span>{strictPosition === 'start' ? t('thumbnail.start') : t('thumbnail.end')}</span>
            </div>
          )}
          
          {/* Page info overlay */}
          <div data-uhuu-chrome className="uhuu:absolute uhuu:bottom-0 uhuu:left-0 uhuu:right-0 uhuu:bg-(--uhuu-thumbnail-caption) uhuu:backdrop-blur-sm uhuu:p-3 uhuu:pointer-events-none">
            <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-2 uhuu:text-white">
              <div className="uhuu:flex-1 uhuu:min-w-0">
                <div className="uhuu:text-sm uhuu:font-medium uhuu:truncate">
                  {localize(item.pageLabel) || t('page.fallbackName', { number: item.pageNum })}
                </div>
              </div>
            </div>
          </div>
          
          {/* Drag indicator */}
          {isDragging && (
            <div data-uhuu-chrome className="uhuu:absolute uhuu:inset-0 uhuu:flex uhuu:items-center uhuu:justify-center uhuu:bg-blue-500/10 uhuu:pointer-events-none">
              <div className="uhuu:text-blue-600 uhuu:font-medium uhuu:text-sm uhuu:bg-white/90 uhuu:px-3 uhuu:py-1 uhuu:rounded-full uhuu:shadow-lg">
                {t('thumbnail.draggingPage')}
              </div>
            </div>
          )}
        </div>
      );
    }
  };
}
