// src/index.js
// The shell's copy of the reset, for its chrome only (the pages keep a template's own base
// styles), and its `uhuu:` utilities, under [data-uhuu-interactive]. Both are unlayered, so the
// reset comes first, as preflight's `base` comes before `utilities`: at equal weight
// (`uhuu:space-y-3`, `:where()`-wrapped by Tailwind) the utility wins.
import './uhuu/styles/uhuu-editor-reset.css';
import './uhuu/styles/uhuu-editor-theme.css';
// Global preflight reset templates lay out against; utilities stay scoped to the shell.
import './uhuu/styles/uhuu-document-base.css';
// Light/dark shell chrome, keyed on <html data-uhuu-appearance> (docs/editor-shell-appearance.md).
import './uhuu/styles/uhuu-appearance.css';

import PaginationStatic from './uhuu/pagination-static/pagination-static';
import SheetStatic from './uhuu/pagination-static/sheet-static';
import { FlowArea, FlowPage, Flow, FlowColumns } from './uhuu/pagination-static/flow-static';
import { FlowText } from './uhuu/pagination-static/flow-text';
import * as flowMeasure from './uhuu/pagination-static/flow-measure';
import {
  createFlowPlanMetrics,
  distributeFlowColumns,
  distributeFlowItems,
} from './uhuu/pagination-static/flow-core';
import { FlowDocument } from './uhuu/pagination-static/flow-document';
import { markdownToFlowItems } from './uhuu/pagination-static/markdown-flow';
import { htmlToFlowItems } from './uhuu/pagination-static/html-flow';
import { planCoverSpread, resolveSheetSize } from './uhuu/pagination-static/spread-core';
import { CoverSpread } from './uhuu/pagination-static/cover-spread';
import { usePaginationHold } from './uhuu/pagination-static/pagination-hold';
import { useView } from './uhuu/pagination-static/view';

// Group Static components
export const Static = {
  Pagination: PaginationStatic,
  Sheet: SheetStatic,
  FlowArea,
  FlowPage,
  Flow,
  FlowColumns,
  // Text a Flow item may split between lines (one per item).
  FlowText,
  // Exposes the same deterministic chunking algorithm used by FlowArea
  // measurements for consumers that already have measured item heights.
  planFlowChunks: distributeFlowItems,
  planFlowColumnChunks: distributeFlowColumns,
  // Optional cost counters for the two planners above. Diagnostic only.
  createFlowPlanMetrics,
  // The DOM reads FlowArea measures with. Hosts that run their own Flow canvas
  // must use these rather than re-deriving them, or their page boundaries can
  // drift from the delivered document by a rounding step.
  flowMeasure,
  FlowDocument,
  markdownToFlowItems,
  htmlToFlowItems,
  // Perfect-binding cover geometry (outer/inner sheet, spine, glue zones). Pure,
  // DOM-free; used by CoverSpread/PageEditor and by hosts that run their own
  // canvas. See docs/printer-cover-spine-support.md.
  planCoverSpread,
  resolveSheetSize,
  // One physical cover sheet (outer/inner) for the Static-only template path.
  CoverSpread,
  // Holds `data-uhuu-pagination` at `measuring` for template work the package cannot see.
  usePaginationHold,
  // The view the pages are drawn for (PageEditor `view`): `print` or `screen`.
  useView,
};

export { default as ImageBlock } from './uhuu/image/image-block';
export { default as Editable } from './uhuu/editable/editable';
// The props Editable/ImageBlock attach, for templates that bind their own element instead of
// wrapping it: renderer guard and `data-uhuu-type` included.
export { getDialogProps } from './uhuu/editable/dialog-props';
// Print-aware thumbnail URL for an ImageObject or URL (encoded, SVG passed through).
export { imageUrl } from './uhuu/image/image-url';
// An image slot that several dialogs write (map, satellite, cadastral, pick, crop, annotation),
// saved as one `uhuu.frame.v1` value: FrameBlock renders and opens it, the read helpers show it
// without the component. Only the editor writes frames, so the reducer is not exported.
export { default as FrameBlock } from './uhuu/frame/frame-block';
export {
  FRAME_SCHEMA,
  FRAME_KEY,
  isFrameValue,
  normalizeFrame,
  toFrameValue,
  frameImage,
  frameDisplay,
  frameOverlays,
  frameActive,
  frameInput,
  frameSourceView,
  frameOptionsOf,
} from './uhuu/frame/frame-helpers';
// Opening a frame from a template's own element, or as an ImageBlock `dialog`.
export { openFrame, frameEditDialog } from './uhuu/frame/frame-dialog.js';
// Current canonical brandkit.json runtime variables with print-safe colours, scoped (with the
// kit's fonts) around the pages.
// A neutral empty image for ImageBlock's `placeholder`, so no template borrows another client's photos.
export { ImagePlaceholder } from './uhuu/image/image-placeholder';
// Folios and running headers: positions are the template's, brand values come from the scope.
export { PageFolio, RunningHeader, folioNumber } from './uhuu/furniture/page-furniture';
export { BrandKitProvider, useBrandKit } from './uhuu/brand-kit/brand-kit-provider';
// Where a payload's kit lives, and the assets a kit carries (logos, collections, map styles), for
// code outside a provider; inside one, `useBrandKit()` has the same helpers bound to the kit.
export {
  BRAND_KIT_PUBLIC_BASE_URL,
  loadBrandKit,
  brandKitLogo,
  brandKitCollection,
  brandKitMapStyle,
  brandKitEnv,
  brandKitSelection,
} from './uhuu/brand-kit/brand-kit-assets';
// The brand's chart colours for chart libraries and the chart dialog, and locale-aware formatting
// with Swiss print conventions.
export { brandChartDialogBrand, brandChartPalette, colorToHex } from './uhuu/brand-kit/brand-kit-chart.js';
export { brandKitLocale, formatNumber, formatMoney, formatDate } from './uhuu/brand-kit/brand-kit-format.js';

// EditorShell components - grouped export only
import { TemplateDataProvider } from './uhuu/editor-shell/document/template-data-provider';
import { PageEditor } from './uhuu/editor-shell/document/page-editor';
import { InteractiveModeProvider, useInteractive } from './uhuu/editor-shell/interactive-mode-context';
import { useIntegrationAdapter } from './uhuu/editor-shell/document/integration-adapter';
import { DocumentOptions } from './uhuu/editor-shell/document/document-options';

export const EditorShell = {
  TemplateDataProvider,
  PageEditor,
  InteractiveModeProvider,
  useInteractive,
  useIntegrationAdapter,
  // Document-level switches for top-level payload keys, written as user edits
  // (docs/document-options.md). Replaces the platform's template theme options.
  DocumentOptions,
};
