import { useEffect, useMemo, useState, useSyncExternalStore } from 'react';
import { createPortal } from 'react-dom';
import { isRendererMode } from '../runtime/host.js';
import { isDev } from '../utility/is-dev';
import { textOf } from '../utility/json.js';
import { useIsoLayoutEffect } from '../utility/use-iso-layout-effect';
import { createPortalContainer } from '../editor-shell/portal-root';
import {
  BRAND_PREVIEW_QUERY_PARAM,
  brandKitChanges,
  brandKitLabel,
  brandKitRelease,
  brandPreviewFromSearch,
  describeBrandKitChange,
  resolveBrandCandidate,
} from './brand-kit-preview.js';

/**
 * The development preview of another brand version (`?brand=`), see brand-kit-preview.js for what
 * it accepts. It runs only on a local development host (localhost, 127.0.0.1, `*.local`) and never in the PDF renderer
 * (`$uhuu_renderer`), and it lives in the page URL only: nothing here writes the payload or
 * storage, and the URL changes only when the developer starts or stops a preview.
 */
export type BrandPreview = { input: string; url: string; version?: string } | { input: string; error: string };

const listeners = new Set<() => void>();
let historySubscribed = false;
// Providers showing a preview, in layout-effect order (children first, so the one closest to the
// pages comes first), and whether theirs renders a candidate.
const barOwners: Array<{ token: object; renders: boolean }> = [];

function notify() {
  listeners.forEach((listener) => listener());
}

function subscribe(listener: () => void) {
  if (!historySubscribed && typeof window !== 'undefined') {
    historySubscribed = true;
    window.addEventListener('popstate', notify);
  }
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

const none = () => null;

/**
 * The developer's own machine. Narrower than `isDev()`, which also counts any URL with a port:
 * a deployed or on-prem page served on a port must never show a brand nobody activated.
 */
function isLocalPreviewHost() {
  const host = window.location.hostname;
  return host === 'localhost' || host === '127.0.0.1' || host === '[::1]' || host === '::1'
    || host.endsWith('.localhost') || host.endsWith('.local');
}

/** Whether a `?brand=` preview may run on this page: a local development host, never the renderer. */
export function brandPreviewAllowed() {
  return typeof window !== 'undefined' && isDev() && isLocalPreviewHost() && !isRendererMode();
}

function readPreviewParam(): string | null {
  return brandPreviewAllowed() ? brandPreviewFromSearch(window.location.search) : null;
}

/** The page's `?brand=` value where a preview may run; `null` elsewhere and on the server. */
export function useBrandPreviewParam(): string | null {
  return useSyncExternalStore(subscribe, readPreviewParam, none);
}

/** Starts (or with `null` stops) a preview: sets `?brand=` in place, without a reload or a history entry. */
export function setBrandPreviewParam(value: string | null) {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  if (value) url.searchParams.set(BRAND_PREVIEW_QUERY_PARAM, value);
  else url.searchParams.delete(BRAND_PREVIEW_QUERY_PARAM);
  window.history.replaceState(window.history.state, '', url.toString());
  notify();
}

/** The candidate `?brand=` names for a template whose own brand is `brandKit`, or `null` without one. */
export function useBrandPreview(brandKit: unknown): BrandPreview | null {
  const param = useBrandPreviewParam();
  return useMemo(
    () => (param === null ? null : (resolveBrandCandidate(param, { brandKit, origin: window.location.href }) as BrandPreview)),
    [param, brandKit],
  );
}

function barOwner() {
  return (barOwners.find((entry) => entry.renders) ?? barOwners[0])?.token ?? null;
}

/**
 * True for the one provider on the page that draws the bar: the one closest to the pages that
 * renders the candidate (nested providers, a default kit around a selected one, each resolve
 * `?brand=` against their own brand), else the first that says why it ignored it.
 */
export function useBrandPreviewBarOwner(preview: BrandPreview | null): boolean {
  const [token] = useState(() => ({}));
  const owner = useSyncExternalStore(subscribe, barOwner, none);
  const active = preview !== null;
  const renders = preview !== null && 'url' in preview;
  useIsoLayoutEffect(() => {
    if (!active) return undefined;
    const entry = { token, renders };
    barOwners.push(entry);
    notify();
    return () => {
      barOwners.splice(barOwners.indexOf(entry), 1);
      notify();
    };
  }, [active, renders, token]);
  return active && owner === token;
}

/**
 * The bar's own portal container, created after mount: the shell's scoped styles reach it. One
 * layer under the shell's portal, so an open menu stays above the bar.
 */
function useBarContainer(): HTMLElement | null {
  const [container, setContainer] = useState<HTMLElement | null>(null);
  useEffect(() => {
    const element = createPortalContainer();
    element.style.zIndex = '9998';
    document.body.appendChild(element);
    setContainer(element);
    return () => {
      element.remove();
      setContainer(null);
    };
  }, []);
  return container;
}

interface BrandPreviewBarProps {
  preview: BrandPreview;
  /** The template's own brand (the `brandKit` prop). */
  templateKit: unknown;
  /** The candidate once it loaded and passed the checks. */
  candidate: Record<string, unknown> | null;
  status: 'loading' | 'ready' | 'error';
  error?: string;
}

const BUTTON = 'uhuu:shrink-0 uhuu:rounded uhuu:px-1.5 uhuu:py-0.5 uhuu:font-medium uhuu:underline-offset-2 uhuu:hover:underline';

/**
 * *Previewing Walde v9 · template uses v8 · What changed (n) · Stop*, fixed at the bottom of the
 * window and never printed (`uhuu-screen-only`). Developer chrome, in English like the DEV menu.
 */
export function BrandPreviewBar({ preview, templateKit, candidate, status, error }: BrandPreviewBarProps) {
  const container = useBarContainer();
  const [open, setOpen] = useState(false);
  const changes = useMemo(() => (candidate ? brandKitChanges(templateKit, candidate) : null), [templateKit, candidate]);
  if (!container) return null;

  const templateName = textOf((templateKit as { name?: unknown } | null)?.name);
  const templateVersion = brandKitRelease(templateKit)?.version;
  let message: string;
  if ('error' in preview) {
    message = `Brand preview ignored: ${preview.error}. The template's brand renders.`;
  } else {
    const version = brandKitRelease(candidate)?.version ?? preview.version;
    const name = textOf(candidate?.name) ?? (preview.version && !candidate ? templateName : undefined);
    const shown = name && version ? `${name} ${version}` : name ? `${name} from ${preview.input}` : version ?? preview.input;
    const uses = !templateVersion
      ? 'its own brand (no version)'
      : name && name !== templateName ? brandKitLabel(templateKit) : templateVersion;
    message = status === 'error'
      ? `${shown} did not load (${error ?? 'unknown error'}). The template's brand renders.`
      : `${status === 'loading' ? 'Loading' : 'Previewing'} ${shown} · template uses ${uses}`;
  }

  // The chrome root positions; its child paints, so the dark appearance's `[data-uhuu-editor]`
  // colour does not override the bar's ink (as for the shell's primary buttons).
  return createPortal(
    <div
      data-uhuu-editor
      data-uhuu-brand-preview={'error' in preview ? 'invalid' : status}
      role="status"
      className="uhuu-screen-only uhuu:fixed uhuu:inset-x-0 uhuu:bottom-3 uhuu:mx-auto uhuu:w-max uhuu:max-w-[min(720px,calc(100vw-24px))]"
    >
      <div className="uhuu:rounded-lg uhuu:bg-gray-900 uhuu:px-3 uhuu:py-2 uhuu:text-xs uhuu:text-(--uhuu-shell-on-inverse) uhuu:shadow-lg">
        <div className="uhuu:flex uhuu:items-center uhuu:gap-2">
          <span className="uhuu:min-w-0">{message}</span>
          {changes ? (
            <button type="button" aria-expanded={open} className={BUTTON} onClick={() => setOpen((value) => !value)}>
              What changed ({changes.length})
            </button>
          ) : null}
          <button type="button" className={BUTTON} onClick={() => setBrandPreviewParam(null)}>
            Stop
          </button>
        </div>
        {open && changes ? (
          <ul data-uhuu-brand-preview-changes="" className="uhuu:mt-2 uhuu:max-h-[40vh] uhuu:overflow-auto uhuu:font-mono uhuu:text-[11px] uhuu:leading-snug">
            {changes.length
              ? changes.map((change) => <li key={`${change.kind}:${change.name}`}>{describeBrandKitChange(change)}</li>)
              : <li>No runtime variable, font or logo differs from the template&apos;s brand.</li>}
          </ul>
        ) : null}
      </div>
    </div>,
    container,
  );
}
