import { useSyncExternalStore } from 'react';
import {
  APPEARANCE_ATTRIBUTE,
  appearanceFromHostMessage,
  normalizeAppearance,
  resolveAppearance,
  subscribeHostAppearance,
  type ShellAppearance,
} from './appearance-core.js';
import { useIsoLayoutEffect } from '../utility/use-iso-layout-effect';

/**
 * The editor shell's appearance (light or dark chrome) for the whole template document. The host
 * names it three ways, and the shell takes the latest:
 *
 * 1. `?appearance=light|dark` on the template URL, applied when this module is evaluated, i.e.
 *    when the template bundle imports the package, before React renders anything;
 * 2. `appearance` in the handshake answer (`{ action: 'shaked', data }`), which the SDK also
 *    re-emits as `loaded`;
 * 3. `{ action: 'appearance', data: { appearance } }` when the user switches while the document
 *    is open (re-emitted as an `appearance` event by SDK 1.2.3+).
 *
 * The shell reads the host's messages itself (source must be the parent window) as well as through
 * `$uhuu`: templates pin an SDK copy (go-expose bundles a content-addressed one), so the SDK in a
 * given template may predate the `appearance` message. The resolved value is written to
 * `<html data-uhuu-appearance>`, where styles/uhuu-appearance.css picks it up. Never a cookie or
 * the OS preference: templates are third-party frames.
 */
let hostAppearance: ShellAppearance | null = null;
// Explicit choices of the mounted providers, in mount order; the latest one is the document's.
// A stack, not a single value, so an unmounting inner provider hands back to the outer one.
const explicitAppearances: ShellAppearance[] = [];
let sdkSubscribed = false;
let messagesSubscribed = false;
const listeners = new Set<() => void>();

function browserWindow(): (Window & Record<string, any>) | null {
  return typeof window === 'undefined' ? null : (window as any);
}

function ambientSources() {
  const win = browserWindow();
  return {
    host: hostAppearance,
    search: win?.location?.search,
    renderer: Boolean(win?.$uhuu_renderer),
  };
}

/** The appearance without a template's explicit choice: host, then `?appearance=`, then light. */
function getAmbientAppearance(): ShellAppearance {
  return resolveAppearance(ambientSources());
}

/** The appearance the document draws: a mounted provider's explicit choice wins. */
export function getDocumentAppearance(): ShellAppearance {
  return resolveAppearance({ ...ambientSources(), explicit: explicitAppearances.at(-1) });
}

function applyDocumentAppearance() {
  const root = browserWindow()?.document?.documentElement;
  if (typeof root?.setAttribute !== 'function') return;
  const appearance = getDocumentAppearance();
  if (root.getAttribute?.(APPEARANCE_ATTRIBUTE) !== appearance) {
    root.setAttribute(APPEARANCE_ATTRIBUTE, appearance);
  }
}

function notify() {
  applyDocumentAppearance();
  listeners.forEach((listener) => listener());
}

function setHostAppearance(appearance: ShellAppearance) {
  if (appearance === hostAppearance) return;
  hostAppearance = appearance;
  notify();
}

function ensureHostSubscriptions() {
  const win = browserWindow();
  if (!win) return;
  if (!sdkSubscribed && typeof win.$uhuu?.listen === 'function') {
    sdkSubscribed = true;
    subscribeHostAppearance(win.$uhuu, setHostAppearance);
  }
  if (!messagesSubscribed && typeof win.addEventListener === 'function') {
    messagesSubscribed = true;
    win.addEventListener('message', (event: MessageEvent) => {
      // Only the host window may set the appearance: origin is not identity when frames share it.
      const parent = win.parent;
      if (!parent || parent === win || event.source !== parent) return;
      const appearance = appearanceFromHostMessage(event.data);
      if (appearance) setHostAppearance(appearance);
    });
  }
}

// Before the first render: the template bundle imports this package before it mounts anything,
// and the handshake can be answered before the template's payload arrives.
ensureHostSubscriptions();
applyDocumentAppearance();

function subscribe(listener: () => void) {
  ensureHostSubscriptions();
  // The import-time write may predate the host's `$uhuu_renderer` flag: settle it once mounted.
  applyDocumentAppearance();
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}


/**
 * The shell's appearance. With `explicit` (InteractiveModeProvider's `appearance` prop) the
 * document follows it while the caller is mounted; otherwise the host's, then `?appearance=`, then
 * light. Always light in the renderer.
 */
export function useShellAppearance(explicit?: string | null): ShellAppearance {
  // Also the server snapshot: without a window there is no host or URL, so it is light there.
  const ambient = useSyncExternalStore(subscribe, getAmbientAppearance, getAmbientAppearance);
  const chosen = normalizeAppearance(explicit);

  useIsoLayoutEffect(() => {
    if (!chosen) return;
    explicitAppearances.push(chosen);
    notify();
    return () => {
      const index = explicitAppearances.lastIndexOf(chosen);
      if (index !== -1) explicitAppearances.splice(index, 1);
      notify();
    };
  }, [chosen]);

  return chosen && !ambientSources().renderer ? chosen : ambient;
}
