import * as React from "react"
import { useContext } from "react"
import { ConfigContext } from "../config/config-provider"
import ImageBleed from './image-bleed'
import type { ImageOption } from './image-with-options'
import { resolveImageAnchorInsets } from './image-anchor-geometry'
import {
  renderOverlay,
  renderOptionsButton,
  useShouldShowOptions,
} from './image-overlay-utils'

interface ImageBleedWithOverlayProps {
  className?: string
  style?: React.CSSProperties
  overlaySvg?: string
  overlayClassName?: string
  options?: ImageOption[]
  dialog?: Record<string, any> | null
  dialogProps?: Record<string, any>
  bleedProps: any
  children?: React.ReactNode
}

const ImageBleedWithOverlay = ({
  className,
  style,
  overlaySvg,
  overlayClassName,
  options = [],
  dialog,
  dialogProps,
  bleedProps,
  children,
}: ImageBleedWithOverlayProps) => {
  const config = useContext(ConfigContext)
  const showOptions = useShouldShowOptions(options)
  const anchorInsets = resolveImageAnchorInsets(
    {
      ...bleedProps,
      pageWidth: bleedProps?.pageWidth ?? config?.page?.width ?? 210,
      bleed: bleedProps?.bleed ?? config?.page?.bleed ?? 0,
    },
    'bleed'
  )

  // `dialogProps` is not applied in bleed mode: the image is positioned on the page and the click
  // target is ImageBleed's own element, which binds `dialog` itself (see ImageBlockProps).

  // Render bleed with overlay inside
  // Pass dialog prop to ImageBleed (it will call getDialogProps internally)
  // No relative wrapper - it breaks absolute positioning! The options button is anchored
  // to the image rect instead (see image-anchor-geometry).
  return (
    <>
      <ImageBleed {...bleedProps} dialog={dialog}>
        {renderOverlay(overlaySvg, overlayClassName)}
        {children}
      </ImageBleed>
      {renderOptionsButton(options, showOptions, anchorInsets)}
    </>
  )
}

export default ImageBleedWithOverlay
