/**
 * Chart colors for chart libraries, which want plain hex. A kit's chart colors reach templates only
 * when the brand set them: Brand Kit publishes `--chart-1…5` in `runtime` only then, so on Auto
 * every template keeps its own palette. `brandChartPalette` returns the brand's colors when it set
 * them, else the template's `fallback`, as `#rrggbb`.
 *
 * Pure and DOM-free.
 */
import { isPlainObject, textOf } from '../utility/json.js';
import { brandKitRuntime, toPrintSafeColor } from './brand-kit-css-vars.js';

const HEX = /^#([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
const NUMBER = '[+-]?(?:\\d+\\.?\\d*|\\.\\d+)';
const RGB = new RegExp(`^rgba?\\(\\s*(${NUMBER})(%?)\\s*[,\\s]\\s*(${NUMBER})(%?)\\s*[,\\s]\\s*(${NUMBER})(%?)`, 'i');
const OKLCH = new RegExp(`^oklch\\(\\s*(${NUMBER})(%?)\\s+(${NUMBER})(%?)\\s+(${NUMBER}|none)(?:deg)?`, 'i');
const OKLAB = new RegExp(`^oklab\\(\\s*(${NUMBER})(%?)\\s+(${NUMBER})(%?)\\s+(${NUMBER})(%?)`, 'i');

const clamp01 = (value) => Math.min(1, Math.max(0, value));
const hex2 = (value) => Math.round(clamp01(value) * 255).toString(16).padStart(2, '0');
const gamma = (linear) => (linear <= 0.0031308 ? 12.92 * linear : 1.055 * Math.pow(linear, 1 / 2.4) - 0.055);

function oklabToHex(l, a, b) {
  // Björn Ottosson's OKLab → linear sRGB.
  const l_ = l + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = l - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = l - 0.0894841775 * a - 1.291485548 * b;
  const [L, M, S] = [l_ ** 3, m_ ** 3, s_ ** 3];
  const r = 4.0767416621 * L - 3.3077115913 * M + 0.2309699292 * S;
  const g = -1.2684380046 * L + 2.6097574011 * M - 0.3413193965 * S;
  const bl = -0.0041960863 * L - 0.7034186147 * M + 1.707614701 * S;
  return `#${hex2(gamma(r))}${hex2(gamma(g))}${hex2(gamma(bl))}`;
}

/**
 * `#rrggbb` for a colour the kit may hold (hex, `rgb()`, HSL, `oklch()`, `oklab()`); alpha is
 * dropped. `undefined` for anything else, keywords included.
 */
export function colorToHex(value) {
  const color = toPrintSafeColor(value);
  if (!color) return undefined;
  const hex = HEX.exec(color);
  if (hex) {
    const digits = hex[1].length <= 4 ? [...hex[1].slice(0, 3)].map((digit) => digit + digit).join('') : hex[1].slice(0, 6);
    return `#${digits.toLowerCase()}`;
  }
  const rgb = RGB.exec(color);
  if (rgb) {
    const channel = (number, percent) => Number(number) / (percent ? 100 : 255);
    return `#${hex2(channel(rgb[1], rgb[2]))}${hex2(channel(rgb[3], rgb[4]))}${hex2(channel(rgb[5], rgb[6]))}`;
  }
  const lch = OKLCH.exec(color);
  if (lch) {
    const l = Number(lch[1]) / (lch[2] ? 100 : 1);
    const c = Number(lch[3]) * (lch[4] ? 0.004 : 1);
    const h = lch[5] === 'none' ? 0 : (Number(lch[5]) * Math.PI) / 180;
    return oklabToHex(l, c * Math.cos(h), c * Math.sin(h));
  }
  const lab = OKLAB.exec(color);
  if (lab) {
    return oklabToHex(Number(lab[1]) / (lab[2] ? 100 : 1), Number(lab[3]) * (lab[4] ? 0.004 : 1), Number(lab[5]) * (lab[6] ? 0.004 : 1));
  }
  return undefined;
}

/** The chart colors the brand set, in series order, as written in the kit. Empty on Auto. */
export function brandKitChartColors(brandKit) {
  if (!isPlainObject(brandKit)) return [];
  const runtime = brandKitRuntime(brandKit);
  if (runtime) {
    // Published kits: present only when authored.
    return [1, 2, 3, 4, 5].map((n) => textOf(runtime.light[`--chart-${n}`])).filter(Boolean);
  }
  // Template-bundled kits: semantic chart1…5 or `chart-1…` aliases.
  const semantic = isPlainObject(brandKit.tokens?.light?.semantic) ? brandKit.tokens.light.semantic : {};
  const aliases = isPlainObject(brandKit.tokens?.light?.aliases) ? brandKit.tokens.light.aliases : {};
  return [1, 2, 3, 4, 5].map((n) => textOf(semantic[`chart${n}`]) ?? textOf(aliases[`chart-${n}`])).filter(Boolean);
}

/**
 * The palette a chart should use, as `#rrggbb`: the brand's chart colors when it set them, else
 * `fallback` (the template's own). `count` repeats the palette to that many series.
 *
 * @param {object|null|undefined} brandKit
 * @param {{ fallback?: string[], count?: number }} [options]
 * @returns {{ colors: string[], source: 'brand'|'template' }}
 */
export function brandChartPalette(brandKit, options = {}) {
  const brand = brandKitChartColors(brandKit).map(colorToHex).filter(Boolean);
  const fallback = (Array.isArray(options.fallback) ? options.fallback : []).map(colorToHex).filter(Boolean);
  const base = brand.length ? brand : fallback;
  const source = brand.length ? 'brand' : 'template';
  const count = Number.isInteger(options.count) && options.count > 0 ? options.count : base.length;
  const colors = base.length ? Array.from({ length: count }, (_, index) => base[index % base.length]) : [];
  return { colors, source };
}

/** A role's colour from the kit: published `runtime` first, then the semantic token. */
function roleColor(brandKit, runtimeName, semanticKey) {
  const runtime = brandKitRuntime(brandKit);
  const fromRuntime = runtime ? textOf(runtime.light[`--${runtimeName}`]) : undefined;
  const semantic = isPlainObject(brandKit?.tokens?.light?.semantic) ? brandKit.tokens.light.semantic[semanticKey] : undefined;
  return colorToHex(fromRuntime ?? semantic);
}

/**
 * The `config.brand` the chart dialog takes (`@uhuu/dialog-contracts` `ChartDialogBrand`): series
 * colours from `brandChartPalette` and the ink, line, muted and surface colours, all `#rrggbb`, so a
 * code template opening the dialog shows the same colours its pages print. Missing roles are left
 * out and the dialog fills them with its neutral defaults.
 *
 *   $uhuu.editDialog({ path, type: 'chart', state, config: { brand: brandChartDialogBrand(kit, { fallback: TEMPLATE_PALETTE }) } })
 *
 * @param {object|null|undefined} brandKit
 * @param {{ fallback?: string[], count?: number }} [options]
 */
export function brandChartDialogBrand(brandKit, options = {}) {
  const { colors } = brandChartPalette(brandKit, options);
  const roles = {
    ink: roleColor(brandKit, 'foreground', 'foreground'),
    line: roleColor(brandKit, 'border', 'border'),
    muted: roleColor(brandKit, 'muted-foreground', 'mutedForeground'),
    surface: roleColor(brandKit, 'background', 'background'),
  };
  return {
    ...(colors.length ? { palette: colors } : {}),
    ...Object.fromEntries(Object.entries(roles).filter(([, value]) => value)),
  };
}
