import { createContext, useContext, useId } from 'react';
import { isRendererMode } from '../runtime/host';
import { warnOnce } from '../utility/diagnostics';
import { useIsoLayoutEffect } from '../utility/use-iso-layout-effect';

/**
 * What the pages are drawn for. `print` (the default) is the document as it prints. `screen` is the
 * document read on screen: pages read it with `useView()` and decide what changes (a table kept
 * whole), and a Flow item with `growSheet` grows its sheet instead of being scaled to fit a page.
 * The PDF renderer always draws `print`.
 */
export type StaticView = 'print' | 'screen';

const VIEWS: readonly StaticView[] = ['print', 'screen'];

/**
 * The view a `PageEditor` `view` prop asks for: `print` in the renderer, whatever was asked, and
 * for anything that is not a view (with a warning naming the value).
 */
export function resolveView(view: unknown): StaticView {
  if (isRendererMode() || view === undefined || view === null) return 'print';
  if ((VIEWS as readonly unknown[]).includes(view)) return view as StaticView;
  const name = JSON.stringify(view) ?? String(view);
  warnOnce(`view:${name}`, `[uhuu-components] PageEditor view ${name} is not "print" or "screen"; the pages are drawn for print.`);
  return 'print';
}

export const StaticViewContext = createContext<StaticView>('print');

/** The view the mounted pages are drawn for, on html: `<html data-uhuu-view="print|screen">`. */
export const VIEW_ATTRIBUTE = 'data-uhuu-view';
const publishers = new Set<string>();

/**
 * Publishes the view a document root draws on `html` while the root is mounted, next to
 * `data-uhuu-pagination`, so a renderer, a host or a template's CSS can read what was drawn
 * (`html[data-uhuu-view="screen"]`), not what was asked: the renderer publishes `print` whatever
 * view it was given. A `PageEditor` publishes its resolved view; a standalone `Static.Pagination`
 * publishes `print`. Several roots on one page agree in practice (they resolve the same way); the
 * last to commit wins. The attribute goes when the last root unmounts.
 */
export function usePublishedView(view: StaticView, enabled = true) {
  const owner = useId();
  useIsoLayoutEffect(() => {
    if (!enabled || typeof document === 'undefined') return undefined;
    publishers.add(owner);
    document.documentElement.setAttribute(VIEW_ATTRIBUTE, view);
    return () => {
      publishers.delete(owner);
      if (!publishers.size) document.documentElement.removeAttribute(VIEW_ATTRIBUTE);
    };
  }, [owner, view, enabled]);
}

/**
 * The view the pages are drawn for: `print` or `screen` (`PageEditor` `view`). Outside a
 * PageEditor, and always in the renderer, `print`.
 */
export function useView(): StaticView {
  const view = useContext(StaticViewContext);
  return isRendererMode() ? 'print' : view;
}
