import type { CSSProperties, ReactNode } from 'react';
import { useBrandKit } from '../brand-kit/brand-kit-provider';

/**
 * Page furniture every print template re-implemented: the folio (page number) with verso/recto
 * positions, and a running header with the brand's mark and a rule. Layout (where, how big) is the
 * template's, in mm; brand values (font, colours, logo) come from the `BrandKitProvider` scope.
 * Render them from `PageEditor`'s `renderOverlay` or inside a page.
 */

/** A position on the sheet in mm; set `left` or `right`, and `top` or `bottom`. */
export interface FurniturePosition {
  left?: number;
  right?: number;
  top?: number;
  bottom?: number;
}

const mm = (value: number | undefined) => (value === undefined ? undefined : `${value}mm`);
const placed = (position: FurniturePosition): CSSProperties => ({
  position: 'absolute',
  left: mm(position.left),
  right: mm(position.right),
  top: mm(position.top),
  bottom: mm(position.bottom),
});

/**
 * The printed page number of sheet `pageNo` (1-based, in deck order), or `null` when that sheet is
 * not numbered. Numbering starts at the first numbered sheet and skips unnumbered sheets after it,
 * so inserting a full-bleed photo page does not shift the count; `offset` is subtracted, for decks
 * whose numbering starts after front matter.
 *
 * @param sheetKeys component key of every sheet in deck order (the editor's own order).
 * @param numbered  the keys that carry a folio, or a predicate.
 */
export function folioNumber({
  pageNo,
  sheetKeys,
  numbered,
  offset = 0,
}: {
  pageNo: number;
  sheetKeys: readonly string[];
  numbered: readonly string[] | ((key: string) => boolean);
  offset?: number;
}): number | null {
  const isNumbered = typeof numbered === 'function' ? numbered : (key: string) => numbered.includes(key);
  const key = sheetKeys[pageNo - 1];
  if (key === undefined || !isNumbered(key)) return null;
  const start = sheetKeys.findIndex(isNumbered);
  const unnumberedBefore = sheetKeys.slice(start, pageNo - 1).filter((sheet) => !isNumbered(sheet)).length;
  return pageNo - offset - unnumberedBefore;
}

interface PageFolioProps {
  /** The number to print (see `folioNumber`); nothing renders for `null`. */
  number: number | null | undefined;
  /** The sheet's position in the deck; even sheets are verso (left-hand), odd ones recto. */
  pageNo: number;
  verso: FurniturePosition;
  recto: FurniturePosition;
  /** Text size in pt (default 9). */
  size?: number;
  className?: string;
  style?: CSSProperties;
}

/** The page number, in the brand's body font and muted text colour, at the verso or recto position. */
export function PageFolio({ number, pageNo, verso, recto, size = 9, className, style }: PageFolioProps) {
  if (number === null || number === undefined) return null;
  const isVerso = pageNo % 2 === 0;
  return (
    <span
      data-uhuu-page-folio={isVerso ? 'verso' : 'recto'}
      className={className}
      style={{
        ...placed(isVerso ? verso : recto),
        fontFamily: 'var(--font-sans)',
        fontSize: `${size}pt`,
        lineHeight: 1,
        color: 'var(--muted-foreground, currentColor)',
        ...style,
      }}
    >
      {number}
    </span>
  );
}

interface RunningHeaderProps {
  /** Where the header band sits; its width spans `left` to `right`. */
  position: FurniturePosition;
  /** Text beside the logo, e.g. the document or section title. */
  children?: ReactNode;
  /** The brand logo to show (`logo({ kind, background })`), or `false` for none. Default: the mark on Paper. */
  logo?: false | { kind?: 'primary' | 'mark' | 'wordmark'; background?: 'light' | 'dark'; name?: string; locale?: string };
  /** Logo height in mm (default 6). */
  logoHeight?: number;
  /** A rule under the header in the brand's `border` or `accent` colour, or none. */
  rule?: 'border' | 'accent' | false;
  className?: string;
  style?: CSSProperties;
}

/** A running header: the brand's logo, a title, and an optional rule, all from the brand scope. */
export function RunningHeader({ position, children, logo = { kind: 'mark' }, logoHeight = 6, rule = 'border', className, style }: RunningHeaderProps) {
  const runtime = useBrandKit();
  const image = logo && runtime ? runtime.logo(logo) : null;
  return (
    <div
      data-uhuu-running-header=""
      className={className}
      style={{
        ...placed(position),
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '4mm',
        paddingBottom: rule ? '2mm' : undefined,
        borderBottom: rule ? `0.25mm solid var(--${rule}, currentColor)` : undefined,
        fontFamily: 'var(--font-sans)',
        color: 'var(--muted-foreground, currentColor)',
        ...style,
      }}
    >
      <span style={{ minWidth: 0 }}>{children}</span>
      {image ? <img src={image.src} alt={image.alt ?? ''} style={{ height: `${logoHeight}mm`, width: 'auto' }} /> : null}
    </div>
  );
}
